/**
 * True when handing `r.smiles` to the property/pKa engines would make them
 * read a DIFFERENT compound: they look the string up in the name/formula
 * dictionary before parsing it as SMILES.
 */
function propertiesWouldMisread(r: StructureResult): boolean {
  const hit = lookupSmiles(r.smiles);
  if (!hit || hit.smiles === r.smiles) return false;
  try {
    return OclMolecule.fromSmiles(hit.smiles).getIDCode() !== r.idcode;
  } catch {
    return true;
  }
}

/** Properties + pKa for a DRAWN structure, from its SMILES — or withheld by name (see above). */
function renderPropertiesFor(r: StructureResult): void {
  if (!propertiesWouldMisread(r)) {
    renderProperties(r.smiles);
    return;
  }
  structurePropsEl.replaceChildren();
  currentProperties = null;
  currentPka = null;
  insertPropsBtn.disabled = true;
  const n = document.createElement("div");
  n.className = "prop-na";
  n.textContent = `Properties not shown: “${r.smiles}” is also a dictionary entry for a different compound, and the property engine would read that one.`;
  structurePropsEl.appendChild(n);
}

/** Attempts to render a 2D structure for the current input and shows it (or a hint). */
function updateStructurePreview(): void {
  const text = inputEl.value.trim();
  currentStructure = null;
  // Editing the name invalidates any prior online lookup / pending consent.
  opsinConfirm.hidden = true;
  setOpsinStatus("");

  if (!text) {
    showStructureHint("Type a name, formula, or SMILES to see its structure.");
    return;
  }

  // v2.137.0: typed input is read by the formula-vs-SMILES rule
  // (structures.resolveStructure): Structure mode is SMILES-first, and when
  // the formula reading differs it is NAMED in a note ("Co" would be cobalt);
  // a string that is only a formula (Fe2O3) is said to have no single
  // structure rather than being drawn as something else.
  let resolved: ReturnType<typeof resolveStructure>;
  try {
    resolved = resolveStructure(text, "auto", STRUCTURE_W, STRUCTURE_H);
  } catch {
    resolved = { kind: "none", message: "No structure found. Try a common name (aspirin), a known formula (C6H6), or a SMILES string." };
  }
  if (resolved.kind === "formula" || resolved.kind === "none") {
    showStructureHint(resolved.message);
    return;
  }
  if (resolved.kind === "ambiguous") {
    // Both readings shown: the message names them; the SMILES drawing is for
    // reference only and is NOT offered for insertion.
    showStructureHint(resolved.message);
    const ref = document.createElement("div");
    ref.innerHTML = resolved.smiles.svg;
    structurePreviewEl.appendChild(ref);
    return;
  }
  const result = resolved.result;

  currentStructure = result;
  structurePreviewEl.innerHTML = result.svg;
  renderStructureInfo(result.formula, result.mw, result.smiles, result.source, text);
  if (resolved.note) {
    const n = document.createElement("span");
    n.className = "structure-warn";
    n.textContent = resolved.note;
    structureInfo.appendChild(n);
  }
  // Properties and pKa from the RESOLVED SMILES, never the typed text: the
  // typed "CO" reads differently in the two dictionaries. computeProperties /
  // predictPka still run their own dictionary look-up first, so a resolved
  // SMILES that is ALSO a dictionary key for a different compound (methanol
  // typed as smiles:CO is "CO", the formula key of carbon monoxide) would get
  // the OTHER compound's properties — those are withheld by name instead.
  renderPropertiesFor(result);
  insertStructureBtn.disabled = false;
  editInDrawBtn.disabled = false;
  if (result.repeatUnit) {
    // A polymer repeat unit (*…*) is not a compound: no name, and the canvas does not take attachment points.
    editInDrawBtn.disabled = true;
    currentStructureName = "";
    structureNameEl.textContent = "No name: a polymer repeat unit (attachment points *) is not a single compound.";
    insertNameBtn.disabled = true;
    return;
  }

  // Names: the curated dictionary first (retained names — aspirin, toluene);
  // on a miss, the offline SYSTEMATIC subset namer speaks if — and only if —
  // the structure is inside its coverage. A refusal is shown by name, never
  // a guessed name: this is a patent tool.
  currentStructureName = nameForIdcode(result.idcode) ?? "";
  if (currentStructureName) {
    structureNameEl.textContent = `Name: ${currentStructureName}`;
  } else {
    try {
      const named = OclMolecule.fromIDCode(result.idcode);
      const sys = iupacName(named);
      if (sys.name) {
        // With its CIP stereodescriptors when every stereo element is given and has a locant ((2R)-butan-2-ol);
        // otherwise the constitutional name, and why the descriptors are not in it.
        let st: ReturnType<typeof stereoText> = { prefix: null, line: null };
        try {
          st = stereoText(named, sys.locants, { reversible: sys.reversible, fromText: true });
        } catch {
          /* the name stands without descriptors */
        }
        currentStructureName = st.prefix ? nameWithDescriptors(sys.name, st.prefix, sys.descriptorAt) : sys.name;
        const stereoNote =
          !st.prefix && sys.caveats.some((c) => /stereodescriptors/i.test(c))
            ? `; stereodescriptors not in the name — ${st.line ?? "not given"}`
            : st.prefix && st.line?.includes("lone-pair centre")
              ? "; a lone-pair centre read from text — confirm its descriptor against the drawing"
              : "";
        structureNameEl.textContent = `Systematic name: ${currentStructureName} (subset namer — verify before filing${stereoNote})`;
      } else {
        structureNameEl.textContent = sys.refusal ? `No name: ${sys.refusal}` : "";
      }
    } catch {
      structureNameEl.textContent = "";
    }
  }
  insertNameBtn.disabled = !currentStructureName;
}

/**
 * Shows formula / MW / SMILES under the structure preview (provenance at a
 * glance), and says so when the input was AMBIGUOUS.
 *
 * A bare molecular formula does not determine a structure: C2H6O is ethanol or
 * dimethyl ether, C6H12O6 is glucose, fructose, galactose and a dozen more. The
 * library resolves it to the most common compound and reports `source` so the UI
 * can be honest about the guess; nothing read that flag until now, so the user
 * saw a confident structure with no hint that a choice had been made on their
 * behalf.
 */
function renderStructureInfo(
  formula: string,
  mw: number,
  smiles: string,
  source?: "name" | "formula" | "smiles",
  input?: string,
): void {
  structureInfo.replaceChildren();
  const bits: string[] = [];
  // Typeset, with its unit (the display contract: C₁₃H₁₈O₂, 206.28 g/mol — it read C13H18O2, MW: 206.28).
  if (formula) bits.push(`Formula: ${formatFormula(formula)}`);
  if (mw) bits.push(`MW: ${mw} g/mol`);
  if (smiles) bits.push(`SMILES: ${smiles}`);
  for (const b of bits) {
    const span = document.createElement("span");
    span.textContent = b;
    structureInfo.appendChild(span);
  }
  if (source === "formula") {
    const warn = document.createElement("span");
    warn.className = "structure-warn";
    const typed = (input ?? "").trim();
    warn.textContent =
      `\u26a0 "${typed}" is a molecular formula, which does not identify one structure. ` +
      `Interpreted as the most common compound with that formula. ` +
      `Paste a SMILES string or a specific name to choose a different isomer.`;
    structureInfo.appendChild(warn);
  }
}

function showStructureHint(message: string): void {
  structurePreviewEl.replaceChildren();
  const hint = document.createElement("span");
  hint.className = "hint";
  hint.textContent = message;
  structurePreviewEl.appendChild(hint);
  structureInfo.replaceChildren();
  structureNameEl.textContent = "";
  structurePropsEl.replaceChildren();
  currentStructureName = "";
  currentProperties = null;
  currentPka = null;
  insertNameBtn.disabled = true;
  insertStructureBtn.disabled = true;
  insertPropsBtn.disabled = true;
  editInDrawBtn.disabled = true;
}

/** One-line druglikeness verdict for a rule screen. */
function ruleVerdict(name: string, r: { pass: boolean; violations: string[] }): string {
  if (r.pass && !r.violations.length) return `${name}: ✓ pass`;
  if (r.pass) return `${name}: ✓ pass (1 violation: ${r.violations.join(", ")})`;
  return `${name}: ✗ fail (${r.violations.join(", ")})`;
}

/**
 * Computes and shows the physicochemical property readout (cLogP, logS, tPSA,
 * H-bond donors/acceptors, rotatable bonds) and the Lipinski/Veber druglikeness
 * screens under the structure. Values are OpenChemLib estimates — advisory.
 */
function renderProperties(input: string): void {
  structurePropsEl.replaceChildren();
  currentProperties = null;
  currentPka = null;
  insertPropsBtn.disabled = true;

  let p: PhysChemProperties | null = null;
  try {
    p = computeProperties(input);
  } catch {
    p = null;
  }
  if (!p) return;

  currentProperties = p;

  const eyebrow = (text: string): void => {
    const e = document.createElement("div");
    e.className = "prop-eyebrow";
    e.textContent = text;
    structurePropsEl.appendChild(e);
  };

  // Metric list: label left, value in a shared right-aligned column.
  eyebrow("Properties");
  const grid = document.createElement("div");
  grid.className = "prop-grid";
  // cLogP and logS are QSAR estimates trained on organic molecules; OpenChemLib
  // returns fallback constants (0 and −0.53) for out-of-domain inputs like bare
  // metals or salts, so show "n/a" there rather than a fake-confident number.
  // Everything else (MW, tPSA, H-bond/rotatable counts) is exact for any input.
  const estimatesInDomain = p.druglikenessApplicable;
  const metrics: [string, string][] = [
    ["MW", `${p.mw}`],
    ["cLogP", estimatesInDomain ? trueMinus(String(p.logP)) : "n/a"],
    ["logS", estimatesInDomain ? trueMinus(String(p.logS)) : "n/a"],
    ["tPSA", `${p.tpsa} Å²`],
    ["H-bond donors", `${p.hbd}`],
    ["H-bond acceptors", `${p.hba}`],
    ["Rotatable bonds", `${p.rotatableBonds}`],
    ["Heavy atoms", `${p.heavyAtoms}`],
  ];
  for (const [k, v] of metrics) {
    const kk = document.createElement("span");
    kk.className = "prop-k";
    kk.textContent = k;
    const vv = document.createElement("span");
    vv.className = "prop-v";
    vv.textContent = v;
    grid.append(kk, vv);
  }
  structurePropsEl.appendChild(grid);

  // Druglikeness: a PASS/FAIL pill per screen, with any criteria on their own line.
  eyebrow("Druglikeness");
  // Lipinski/Veber are upper-bound filters for organic small molecules, so they
  // are vacuously "passed" by bare metals, noble gases, and simple salts. Show a
  // plain "n/a" note for those rather than a misleading green pass.
  if (!p.druglikenessApplicable) {
    const na = document.createElement("div");
    na.className = "prop-na";
    na.textContent = "n/a — applies to organic small molecules";
    structurePropsEl.appendChild(na);
    // The caveats must survive this early exit. An out-of-domain input is the
    // case that needs them MOST — it is the one where the numbers above mean
    // least — so returning before rendering them would be exactly backwards.
    structurePropsEl.appendChild(aboutEstimates(p.caveats));
    insertPropsBtn.disabled = false;
    return;
  }
  const rules = document.createElement("div");
  rules.className = "prop-rules";
  const ruleData: [string, RuleResult][] = [
    ["Lipinski Ro5", p.lipinski],
    ["Veber", p.veber],
  ];
  for (const [name, r] of ruleData) {
    const row = document.createElement("div");
    row.className = "prop-rule";
    const pill = document.createElement("span");
    pill.className = `prop-pill ${r.pass ? "pass" : "fail"}`;
    pill.textContent = r.pass ? "Pass" : "Fail";
    const nm = document.createElement("span");
    nm.className = "prop-name";
    nm.textContent = name;
    row.append(pill, nm);
    if (r.violations.length) {
      const why = document.createElement("span");
      why.className = "prop-why";
      why.textContent = r.violations.join(" · ");
      row.appendChild(why);
    }
    rules.appendChild(row);
  }
  structurePropsEl.appendChild(rules);

  // Same block the Spectra modes use. cLogP sitting bare next to a carefully
  // caveated NMR prediction taught the reader that a JurisLab number is
  // trustworthy by default — which is the opposite of the point.
  structurePropsEl.appendChild(aboutEstimates(p.caveats));

  renderPka(input);
  insertPropsBtn.disabled = false;
}

/**
 * Computes the pairwise alignment for the current inputs and shows it.
 *
 * The alignment is rendered — and inserted — in a MONOSPACE font. That is not
 * cosmetic: an alignment is a column-wise claim, and a proportional font silently
 * destroys the correspondence between the ruler and the residues beneath it. A
 * misaligned alignment is a wrong figure, not an ugly one.
 */
function updateAlign(): void {
  currentAlignText = "";
  alignInsertBtn.disabled = true;
  const a = alignA.value.trim();
  const b = alignB.value.trim();
  if (!a || !b) {
    alignResult.innerHTML = '<span class="hint">Paste two sequences to align.</span>';
    return;
  }

  const kindSel = alignKindSel.value;
  let r;
  try {
    r = align(a, b, {
      mode: alignModeSel.value as AlignMode,
      kind: kindSel === "auto" ? undefined : (kindSel as SeqKind),
    });
  } catch {
    r = null;
  }
  if (!r) {
    // align() returns null for two different reasons, and they need different
    // messages. Past MAX_ALIGN_CELLS it refuses on SIZE — reporting that as
    // "nothing alignable" would blame the user's sequences for a limit, on
    // input that is perfectly valid. Below the cap, null really does mean the
    // input had nothing in it.
    const tooBig = alignSizeRefusal(a, b);
    alignResult.innerHTML = tooBig
      ? `<span class="hint">${esc(tooBig)}</span>`
      : '<span class="hint">Nothing alignable in one of the inputs.</span>';
    return;
  }

  const block = formatAlignment(r, 60, "A", "B");
  // A local alignment with no positive-scoring segment has nothing to count: say so, not "Length 0 · Identity 0/0".
  const stats = r.noAlignment
    ? `${r.mode === "global" ? "Global (Needleman–Wunsch)" : "Local (Smith–Waterman)"} · ${r.noAlignment}`
    :
    `${r.mode === "global" ? "Global (Needleman–Wunsch)" : "Local (Smith–Waterman)"} · ` +
    `${r.kind === "protein" ? "BLOSUM62" : "DNA +5/−4"}\n` +
    `Score ${r.score} · Length ${r.length}\n` +
    `Identity ${r.identities}/${r.length} (${r.percentIdentity}%) · ` +
    `Similarity ${r.similarities}/${r.length} (${r.percentSimilarity}%) · ` +
    `Gaps ${r.gaps}/${r.length} (${r.percentGaps}%)`;

  alignResult.innerHTML = "";
  const head = document.createElement("div");
  head.textContent = stats;
  head.style.whiteSpace = "pre-wrap";
  const pre = document.createElement("pre");
  pre.textContent = block;
  pre.style.fontFamily = "Consolas, 'Courier New', monospace";
  pre.style.overflowX = "auto";
  pre.style.margin = "8px 0";
  alignResult.append(head, pre);
  alignResult.appendChild(specCaveats(r.caveats));

  // The document gets the same thing the pane shows, caveats included — a percent
  // identity that lands in a paper without its gap costs is a number without a
  // meaning.
  currentAlignText = `${stats}\n\n${block}\n\n${r.caveats.map((c) => `• ${c}`).join("\n")}`;
  alignInsertBtn.disabled = false;
}

/** Detects ionizable groups and appends a pKa block to the properties panel. */
function renderPka(input: string): void {
  currentPka = null;
  let res: PkaResult | null = null;
  try {
    res = predictPka(input);
  } catch {
    return;
  }
  if (!res) return;
  currentPka = res;
  const block = document.createElement("div");
  block.className = "prop-rules";
  const head = document.createElement("div");
  head.className = "prop-name";
  head.textContent = res.sites.length ? "Ionizable groups (estimated pKₐ)" : "No common ionizable groups detected";
  block.appendChild(head);
  for (const s of res.sites) {
    const row = document.createElement("div");
    row.className = "prop-rule";
    row.textContent = `${s.group} — ${s.kind === "acid" ? "acidic" : "basic"}, ${s.kind === "acid" ? "pKₐ" : "pKₐH"} ≈ ${s.pka}`;
    block.appendChild(row);
    // Show the derivation when a substituent correction was applied.
    if (s.note) {
      const why = document.createElement("div");
      why.className = "prop-why";
      why.textContent = s.note;
      block.appendChild(why);
    }
  }
  if (res.sites.length) {
    const net = document.createElement("div");
    net.className = "prop-why";
    net.textContent = `Est. net charge at pH 7.4: ${res.netChargeAt74 >= 0 ? "+" : "−"}${Math.abs(res.netChargeAt74).toFixed(2)}`;
    block.appendChild(net);
  }
  const caveat = document.createElement("div");
  caveat.className = "prop-why";
  caveat.textContent = "Estimates. Aromatic acids/bases and aliphatic acids are adjusted for their substituents (Hammett / inductive, ±0.3–0.5); other groups use the typical value for the detected group.";
  block.appendChild(caveat);
  structurePropsEl.appendChild(block);
}

/** Multi-line plain-text pKa summary for insertion (empty when nothing detected). */
function pkaAsText(res: PkaResult | null): string {
  if (!res || !res.sites.length) return "";
  const lines: string[] = [];
  for (const s of res.sites) {
    lines.push(`  ${s.group}: ${s.kind === "acid" ? "acidic" : "basic"}, ${s.kind === "acid" ? "pKₐ" : "pKₐH"} ≈ ${s.pka}`);
    if (s.note) lines.push(`    (${s.note})`);
  }
  return [
    "Ionizable groups (estimated pKₐ; aromatic acids/bases and aliphatic acids are substituent-corrected):",
    ...lines,
    `Estimated net charge at pH 7.4: ${res.netChargeAt74 >= 0 ? "+" : "−"}${Math.abs(res.netChargeAt74).toFixed(2)}`,
  ].join("\n");
}

/** Multi-line plain-text property summary for insertion into the document. */
function propertiesAsText(p: PhysChemProperties | null): string {
  if (!p) return "";
  const est = p.druglikenessApplicable; // cLogP/logS QSAR estimates apply to organic small molecules only
  return [
    `Physicochemical properties — ${formatFormula(p.formula)} (MW ${p.mw} g/mol)`,
    `cLogP: ${est ? trueMinus(String(p.logP)) : "n/a (outside model domain)"}`,
    `logS: ${est ? `${trueMinus(String(p.logS))} (log mol/L)` : "n/a (outside model domain)"}`,
    `Topological PSA: ${p.tpsa} Å²`,
    `H-bond donors: ${p.hbd}`,
    `H-bond acceptors: ${p.hba}`,
    `Rotatable bonds: ${p.rotatableBonds}`,
    `Heavy atoms: ${p.heavyAtoms}`,
    ...(p.druglikenessApplicable
      ? [ruleVerdict("Lipinski Rule of Five", p.lipinski), ruleVerdict("Veber rule", p.veber)]
      : ["Druglikeness: n/a (screens apply to organic small molecules)"]),
    "Estimated values (OpenChemLib) — verify before relying on them.",
    ...(pkaAsText(currentPka) ? ["", pkaAsText(currentPka)] : []),
  ].join("\n");
}

function setOpsinStatus(message: string, kind: "" | "error" | "success" = ""): void {
  opsinStatusEl.textContent = message;
  opsinStatusEl.className = kind ? `opsin-status ${kind}` : "opsin-status";
}

/**
 * Handles the "Resolve name online" button. On the first use this session it
 * shows the in-pane consent step (an Office add-in can't rely on window.confirm);
 * Consent is per NAME: a name already sent this session goes straight through,
 * anything new always asks first.
 */
function onOpsinClick(): void {
  const name = inputEl.value.trim();
  if (!name) {
    setOpsinStatus("Type a name in the box above first.", "error");
    return;
  }
  if (opsinConsentedNames.has(opsinKey(name))) {
    void doOpsinLookup(name);
    return;
  }
  // Consent gate: the name is about to leave the machine — make that explicit.
  opsinPendingName = name;
  opsinConfirmText.textContent =
    `Send “${name}” to the EMBL-EBI OPSIN service over the internet to resolve its structure? ` +
    `Don't do this for confidential compound names.`;
  opsinConfirm.hidden = false;
  setOpsinStatus("");
}

/** Calls OPSIN for `name` and renders the returned structure (offline depiction). */
async function doOpsinLookup(name: string): Promise<void> {
  opsinBtn.disabled = true;
  setOpsinStatus(`Looking up “${name}” online…`);
  try {
    const outcome = await resolveNameOnline(name);
    if (!outcome.ok) {
      setOpsinStatus(outcome.message, "error");
      return;
    }
    renderResolvedSmiles(outcome.result, name);
  } finally {
    opsinBtn.disabled = false;
  }
}

/** Depicts an OPSIN-resolved SMILES in the structure preview (all offline from here). */
function renderResolvedSmiles(result: OpsinResult, name: string): void {
  let structure: ReturnType<typeof renderStructure> = null;
  try {
    // smiles: — OPSIN's output IS a structure; the formula dictionary must not
    // re-read a short SMILES ("CO") as a different compound.
    structure = renderStructure(`smiles:${result.smiles}`, STRUCTURE_W, STRUCTURE_H);
  } catch {
    structure = null;
  }
  if (!structure) {
    setOpsinStatus(`OPSIN parsed “${name}” but its structure couldn't be drawn.`, "error");
    return;
  }
  currentStructure = structure;
  structurePreviewEl.innerHTML = structure.svg;
  renderStructureInfo(structure.formula, structure.mw, structure.smiles);
  renderPropertiesFor(structure);
  insertStructureBtn.disabled = false;
  editInDrawBtn.disabled = false;
  // The user typed the name, so offer it for insertion directly.
  currentStructureName = name;
  structureNameEl.textContent = `Name: ${name}`;
  insertNameBtn.disabled = false;
  const key = result.inchikey ? ` · InChIKey ${result.inchikey}` : "";
  setOpsinStatus(`Resolved “${name}” via OPSIN.${key}`, "success");
}

function setStatus(message: string, kind: "" | "error" | "success" = ""): void {
  statusEl.textContent = message;
  statusEl.className = kind ? `status ${kind}` : "status";
}

/** Builds machine-readable provenance for a structure's image alt-text. */
function provenanceAltText(label: string, formula: string, mw: number, smiles: string, idcode: string): string {
  const meta: string[] = [];
  if (formula) meta.push(formula);
  if (mw) meta.push(`MW ${mw}`);
  if (smiles) meta.push(`SMILES ${smiles}`);
  if (idcode) meta.push(`OCL-ID ${idcode}`);
  return meta.length ? `${label} — ${meta.join("; ")}` : label;
}

/**
 * True if a WordApi requirement-set version is available on this host. Used to
 * gate the OOXML/OMML inserts that older Word (or some web/Mac hosts) lack, so
 * they degrade gracefully instead of throwing a raw exception. Optimistic if the
 * capability can't be determined.
 */
function wordApiSupported(version: string): boolean {
  return docHost.wordApiSupported(version);
}

/** Inserts the formula at the selection — as a native equation, or as formatted text. */
async function insertFormula(): Promise<void> {
  const text = inputEl.value.trim();
  if (!text) {
    setStatus("Type a formula first.", "error");
    return;
  }

  // Math mode with the equation option checked: try OMML first, then fall back
  // to inline formatting if the expression can't be parsed into an equation, or
  // if this host doesn't support native-equation (OOXML) insertion.
  if (currentMode() === "math" && ommlCheckbox.checked) {
    if (!wordApiSupported("1.3")) {
      setStatus("Native equations aren’t supported in this version of Word — inserted as formatted text.", "");
    } else {
      const inserted = await insertEquation(text);
      if (inserted) return;
      setStatus("Couldn't build an equation from that — inserted as formatted text instead.", "error");
    }
  }

  await insertFormattedText(text);
}

/**
 * Inserts the formula as formatted text by inserting the exact same <sub>/<sup>
 * HTML shown in the preview. Using insertHtml (rather than building runs
 * imperatively) keeps run boundaries and formatting deterministic, so the
 * inserted result always matches the preview.
 */
async function insertFormattedText(text: string): Promise<void> {
  const html = segmentsToHtml(parse(text, currentMode()));
  insertBtn.disabled = true;

  try {
    await docHost.insertAtSelection({ kind: "html", content: html, at: "replace", select: "inserted" });
    setStatus("Inserted.", "success");
    recordInsert(currentMode() as HistoryKind, text, text);
  } catch (error) {
    setStatus(`Could not insert: ${(error as Error).message}`, "error");
  } finally {
    insertBtn.disabled = false;
  }
}

/**
 * Builds OMML from the input and inserts it as a native Word equation.
 * Returns true on success, false if the expression couldn't be parsed (so the
 * caller can fall back to formatted text).
 */
async function insertEquation(text: string): Promise<boolean> {
  // Reserve a number only if this expression actually parses (avoid gaps on failure).
  const numbered = numberCheckbox.checked;
  // (I), (II) … are counted here (patent formulas); (1) and (2.1) are Word's own SEQ fields, cross-referenceable.
  const fieldNumbered = numbered && (numberStyleSel?.value ?? "roman") !== "roman";
  let ooxml: string;
  try {
    mathToOoxml(text); // parses, or the caller falls back — before a number is registered
  } catch {
    return false; // parse error — caller falls back
  }
  if (fieldNumbered) {
    const runs = await captionsPane.equationNumber(text, numberStyleSel.value === "chapter");
    if (!runs) return true; // refused; the status said why
    ooxml = mathToOoxml(text, { numberRunsXml: runs });
  } else {
    const label = numbered ? `(${toRoman(peekFormulaNumber())})` : undefined;
    ooxml = mathToOoxml(text, { number: label });
  }

  insertBtn.disabled = true;
  setStatus("Inserting equation…");
  try {
    await docHost.insertAtSelection({ kind: "ooxml", content: ooxml, at: "replace", select: null, tag: "formula-inserter:equation" });
    let fieldNote = "";
    if (fieldNumbered) fieldNote = await captionsPane.afterEquation();
    else if (numbered) {
      nextFormulaNumber(); // consume the number now that it's placed
      updateNumberLabel();
    }
    setStatus(`Equation inserted.${fieldNote}`, fieldNote ? "" : "success");
    recordInsert("math", text, text);
    return true;
  } catch (error) {
    setStatus(`Could not insert equation: ${(error as Error).message}`, "error");
    return true; // a Word/runtime error is not a parse failure; don't double-insert
  } finally {
    insertBtn.disabled = false;
  }
}

/** Rasterizes the current structure SVG to a PNG and inserts it as an inline picture. */
async function insertStructure(): Promise<void> {
  const structure = currentStructure;
  if (!structure) {
    setStatus("No structure to insert.", "error");
    return;
  }

  insertStructureBtn.disabled = true;
  setStatus("Inserting structure…");

  try {
    const d = readSvgDims(structure.svg, STRUCTURE_W, STRUCTURE_H);
    const base64 = await renderFigurePng(structure.svg, d.w, d.h);
    const label = inputEl.value.trim();
    const alt = provenanceAltText(
      structure.repeatUnit ? `2D structure of ${label} (polymer repeat unit; formula and MW per repeat unit)` : `2D structure of ${label}`,
      structure.formula,
      structure.mw,
      structure.smiles,
      structure.idcode,
    );
    await docHost.insertPictureAtSelection({
      base64: base64,
      widthPt: figurePoints(d.w),
      heightPt: figurePoints(d.h),
      alt: alt,
      selectAfter: true,
      tag: "formula-inserter:structure",
    });
    setStatus("Structure inserted.", "success");
    if (label) recordInsert("chemical", label, label);
  } catch (error) {
    setStatus(`Could not insert structure: ${(error as Error).message}`, "error");
  } finally {
    insertStructureBtn.disabled = false;
  }
}

/** Switches Build mode between the drawing canvas and the typed-text surface. */
function setBuildTab(tab: "draw" | "text"): void {
  buildTab = tab;
  const draw = tab === "draw";
  buildTabDrawBtn.classList.toggle("active", draw);
  buildTabTextBtn.classList.toggle("active", !draw);
  buildTabDrawBtn.setAttribute("aria-selected", String(draw));
  buildTabTextBtn.setAttribute("aria-selected", String(!draw));
  buildDrawWrap.style.display = draw ? "block" : "none";
  buildTextWrap.style.display = draw ? "none" : "block";
  const more = document.getElementById("draw-insert-more");
  if (more) more.style.display = draw ? "flex" : "none";
  if (draw) {
    ensureDrawEditor();
    // Creation can fail and fall back to the Text tab; only refresh if it stuck.
    if (drawEditor) updateDrawPreview();
  } else {
    // Peeking at the other tab must not wipe typed R-group definitions just
    // because that tab's input happens to be empty.
    keepRgroupValues = true;
    try {
      updateBuildPreview();
    } finally {
      keepRgroupValues = false;
    }
  }
}

/** Creates the canvas editor on first use (it measures its host, so the host
 *  must be visible). If the webview can't host it, falls back to the Text tab. */
/** Both editors report changes the same way: a programmatic change keeps the status its path just set. */
function onDrawChange(event: CanvasChange): void {
  // Worked out once drawing pauses (the formula and SMILES of a large drawing take a good part of a second):
  // clicks stay quick, Insert works it out first.
  scheduleDrawPreview(!event.isUserEvent || !!event.keepStatus);
}

const drawEditorHost = { setStatus: (m: string, k?: "success" | "error" | "") => setStatus(m, k ?? ""), downloadFile: (blob: Blob, name: string) => triggerDownload(blob, name) };

function ensureDrawEditor(): void {
  if (drawEditor) return;
  const host = document.getElementById("build-editor") as HTMLElement;
  try {
    // The structure editor (OpenChemLib's ChemDraw-like editor): it blocks what cannot be drawn and corrects the
    // drawing as it goes. It was replaced by the page canvas in v2.156 and brought back after a live demo.
    structureEditor = createStructureEditor(host, drawEditorHost);
    structureEditor.setOnChangeListener(onDrawChange);
    drawEditor = structureEditor;
  } catch (error) {
    drawEditor = null;
    structureEditor = null;
    // The constructor appends its root element before the steps that can throw —
    // clear it so a retried click doesn't stack dead editor shells in the host.
    host.replaceChildren();
    // Switch first, THEN report: the tab switch refreshes the Text preview,
    // which clears the status line and would swallow this message.
    setBuildTab("text");
    setStatus(`Drawing canvas unavailable here: ${(error as Error).message}`, "error");
  }
}

/**
 * Nothing drawn: no page objects AND no atoms. The structure editor's page can be empty under a real molecule (one the
 * ChemDraw page writer refuses — a query it has no attribute for), and that is not an empty canvas (review).
 */
function drawingEmpty(): boolean {
  return !drawEditor || (!drawEditor.page().objects.length && !drawEditor.getMolecule().getAllAtoms());
}

/** Shows the structure editor (the default) and makes it the one the pane reads. */
function useStructureEditor(): void {
  ensureDrawEditor();
  if (!structureEditor) return;
  structureEditor.element.hidden = false;
  (document.getElementById("build-page") as HTMLElement).hidden = true;
  (document.getElementById("build-page-bar") as HTMLElement).hidden = true;
  (document.getElementById("build-page-bare") as HTMLElement).hidden = true;
  (document.getElementById("draw-save-cdxml") as HTMLElement).hidden = false;
  drawEditor = structureEditor;
}

/** Shows the page canvas (a ChemDraw page: brackets, arrows, captions) and makes it the one the pane reads. */
function usePageCanvas(): ChemCanvas | null {
  ensureDrawEditor();
  const host = document.getElementById("build-page") as HTMLElement;
  host.hidden = false;
  if (!pageEditor) {
    try {
      pageEditor = createChemCanvas(host, drawEditorHost);
      pageEditor.setOnChangeListener(onDrawChange);
    } catch (error) {
      host.hidden = true;
      setStatus(`The page canvas is unavailable here: ${(error as Error).message}`, "error");
      return null;
    }
  }
  if (structureEditor) structureEditor.element.hidden = true;
  (document.getElementById("build-page-bar") as HTMLElement).hidden = false;
  // Shown again only by a gallery pick that has a structure to offer (it went stale on the whole page: review).
  (document.getElementById("build-page-bare") as HTMLElement).hidden = true;
  pickedBare = null;
  (document.getElementById("draw-save-cdxml") as HTMLElement).hidden = true;
  drawEditor = pageEditor;
  return pageEditor;
}

/**
 * The canvas for organometallic drawing: the page canvas, switched to in place. Coming from the structure editor, what
 * is drawn there comes along (the page canvas holds everything the editor does); already on the page canvas, it stays.
 */
function organoCanvas(): ChemCanvas | null {
  if (pageEditor && drawEditor === pageEditor) return pageEditor;
  const mol = structureEditor && structureEditor.getMolecule().getAllAtoms() ? structureEditor.getMolecule().getCompactCopy() : null;
  const frag = structureEditor?.isFragment() ?? false;
  const pc = usePageCanvas();
  if (!pc) return null;
  // An empty structure editor leaves the page canvas as it was (back from it, its drawing is still there — review).
  if (mol) {
    // A carried drawing replaces the page document; refused by the page writer, the page is the same object and
    // its reason is the status — nothing is placed over it, on the old page or otherwise (review round 2).
    const before = pc.page();
    pc.setMolecule(mol);
    if (pc.page() === before) return null;
    pc.setFragment(frag);
  }
  return pc;
}

/** The structure (brackets and labels left out) of what the page canvas is showing from the gallery, if any. */
let pickedBare: OclMolecule | null = null;

/** The ChemDraw file the gallery is showing, and its name. */
let galleryDoc: CdxDoc | null = null;
let galleryName = "";

function closeChemdrawGallery(): void {
  (document.getElementById("chemdraw-gallery") as HTMLElement).hidden = true;
  (document.getElementById("chemdraw-gallery-grid") as HTMLElement).replaceChildren();
  galleryDoc = null;
}

/** Opens one picked structure: in the structure editor when it is exactly a molecule, else on its own on the page canvas. */
function openPickedStructure(doc: CdxDoc, name: string, st: PageStructure, n: number, total: number): void {
  const of = total > 1 ? `structure ${n} of ${total} from ${name}` : name;
  if (st.mol) {
    useStructureEditor();
    if (!drawEditor) return;
    const mol = st.mol.getCompactCopy();
    drawEditor.setMolecule(mol);
    drawEditor.setName(name);
    drawFromPicture = false;
    setStatus(`Opened ${of} in the structure editor — edit it, then Insert.`, "success");
  } else {
    const sub = subsetPage(doc, st.ids);
    const pc = sub ? usePageCanvas() : null;
    if (!sub || !pc) return void setStatus(`Could not open ${of}.`, "error");
    pc.loadPage(sub);
    pc.setName(name);
    drawFromPicture = false;
    pickedBare = st.bare; // after usePageCanvas, which clears it
    (document.getElementById("build-page-bare") as HTMLElement).hidden = !st.bare;
    setStatus(
      `Opened ${of} on the page canvas, as drawn — ${st.reason}.` +
        (st.bare ? " To change the structure itself, use “Edit the structure in the structure editor” below it." : ""),
      "",
    );
  }
  document.getElementById("build-draw-wrap")?.scrollIntoView({ block: "start" });
}

/** A ChemDraw file or picture: one plain structure opens to edit at once; anything more is a gallery to pick from. */
function openChemdrawPage(page: CdxDoc, name: string): boolean {
  setMode("build");
  setBuildTab("draw");
  ensureDrawEditor();
  if (!drawEditor) return false;
  const { structures, more } = pageStructures(page);
  const extras = page.objects.some((o) => o.items.some((it) => it.kind !== "fragment")) || page.brackets.length > 0;
  if (structures.length === 1 && !extras && !more) {
    closeChemdrawGallery();
    openPickedStructure(page, name, structures[0], 1, 1);
    drawFromPicture = name === "The ChemDraw picture";
    return true;
  }
  if (!structures.length) {
    // Captions and arrows only: the page canvas, as drawn.
    const pc = usePageCanvas();
    if (!pc) return false;
    pc.loadPage(page);
    pc.setName(name);
    setStatus(`${name} has no structures — it opened on the page canvas as drawn.`, "");
    return true;
  }
  galleryDoc = page;
  galleryName = name;
  const grid = document.getElementById("chemdraw-gallery-grid") as HTMLElement;
  grid.replaceChildren();
  structures.forEach((st, i) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "chemdraw-pick" + (st.mol ? "" : " page-only");
    b.setAttribute("role", "listitem");
    b.title = st.mol ? `Structure ${i + 1}: open it in the structure editor` : `Structure ${i + 1}: opens on the page canvas (${st.reason})`;
    // The page's own renderer drew it (its text is escaped there): shown as is.
    b.innerHTML = st.svg;
    const cap = document.createElement("span");
    cap.className = "chemdraw-pick-n";
    cap.textContent = String(i + 1);
    b.appendChild(cap);
    b.addEventListener("click", () => openPickedStructure(page, name, st, i + 1, structures.length));
    grid.appendChild(b);
  });
  const molCount = structures.filter((st) => st.mol).length;
  (document.getElementById("chemdraw-gallery-title") as HTMLElement).textContent =
    `${name}: ${structures.length + more} structure${structures.length + more === 1 ? "" : "s"}` + (more ? ` (the first ${structures.length} shown)` : "");
  (document.getElementById("chemdraw-gallery") as HTMLElement).hidden = false;
  document.getElementById("chemdraw-gallery")?.scrollIntoView({ block: "start" });
  setStatus(
    `${name} opened — click a structure to edit it. ${molCount} of ${structures.length} open in the structure editor` +
      (molCount < structures.length ? "; the others (polymer brackets, counter-ions, generic atoms such as X) open on their own on the page canvas, as drawn." : "."),
    "success",
  );
  drawFromPicture = name === "The ChemDraw picture";
  return true;
}

/** Refreshes whichever Build-mode surface is active (used at mode entry). */
function refreshBuildPreview(): void {
  if (buildTab === "draw") {
    ensureDrawEditor();
    if (drawEditor) updateDrawPreview();
  } else {
    updateBuildPreview();
  }
}

/** Marks the drawn structure generic (a Markush query) or specific again. */
function onFragmentToggle(): void {
  if (!drawEditor) return;
  drawEditor.setFragment(buildFragmentToggle.checked);
  // moleculeChanged() fires the change listener (deferred, as a NON-user
  // event), which refreshes the preview — no explicit refresh here or it runs
  // twice. Non-user refreshes preserve the status line, but this toggle IS a
  // user action, so clear any stale status the old refresh used to clear.
  setStatus("");
  drawEditor.moleculeChanged();
}

/** Wipes the drawing canvas back to a fresh start (recoverable via the editor's undo). */
function onResetCanvas(): void {
  if (!drawEditor) return;
  drawEditor.clearAll(); // stores an undo state first, so a mis-click is recoverable
  // A reset is a fresh start, so the Markush flag goes too (clearAll preserves
  // it, mirroring the toolbar's clear tool). Typed R-group definitions are NOT
  // wiped: undo restores only the molecule, so deleting them here would make a
  // mis-click permanently destroy typed legend text — they stay, invisible,
  // exactly as when the R1 atom itself is erased and redrawn.
  drawEditor.setFragment(false);
  // clearAll's own change event is deferred — and absent on an already-empty
  // canvas — so reflect the reset now (unchecks the Markush box).
  updateDrawPreview();
}

/**
 * Re-lays out the drawn structure with machine-generated clean coordinates
 * (untangles overlaps and distorted rings; connectivity, charges and stereo
 * are untouched). Problems clean-up cannot fix — an exceeded valence, an
 * unbalanced charge — stay reported in the compliance note under the canvas.
 */
function onCleanStructure(): void {
  if (!drawEditor) return;
  if (drawingEmpty()) {
    setStatus("Nothing to clean — the canvas is empty.", "error");
    return;
  }
  // Each structure (the selected ones, if any) is laid out again in place; captions, arrows and the other
  // structures keep their places; group labels stay labels. One Undo step.
  if (!drawEditor.clean()) return;
  updateDrawPreview();
  let remaining = false;
  try {
    remaining = complianceIssues(drawEditor.getMolecule()).some((i) => i.severity === "error");
  } catch {
    // A failed re-check must not turn a successful clean into a thrown click.
  }
  if (remaining) {
    setStatus("Layout cleaned — but the structure itself is not compliant (see the note below the canvas).", "error");
  } else {
    setStatus("Structure cleaned.", "success");
  }
}

/** Renders the compliance note under the canvas (empty = nothing to report). */
/**
 * The Build readout's stereo line (CIP R/S, E/Z — lib/cip.ts): the systematic name with its stereodescriptors when the
 * subset namer names the structure and every stereo element is given ("(2R)-butan-2-ol"), else what is given and what
 * is not, and why. Hidden with no stereo element; never takes the preview down.
 */
function showBuildStereo(mol: OclMolecule | null, fromText = false): void {
  const box = document.getElementById("build-stereo");
  const text = document.getElementById("build-stereo-text");
  if (!box || !text) return;
  box.hidden = true;
  if (!mol || !mol.getAllAtoms() || mol.isFragment()) return;
  try {
    const sys = iupacName(mol);
    const st = stereoText(mol, sys.locants, { reversible: sys.reversible, fromText });
    if (!st.line) return;
    const lead = "Stereo (CIP): ";
    const body = st.line.startsWith(lead) ? st.line.slice(lead.length) : st.line;
    // The name carrying its descriptors says it all ((2R)-butan-2-ol); otherwise what is given and what is not.
    text.textContent = st.prefix && sys.name ? nameWithDescriptors(sys.name, st.prefix, sys.descriptorAt) : body;
    box.hidden = false;
  } catch {
    box.hidden = true;
  }
}

function renderCompliance(issues: ComplianceIssue[]): void {
  drawComplianceEl.replaceChildren();
  drawComplianceEl.classList.remove("bad");
  if (!issues.length) return;
  const errors = issues.some((i) => i.severity === "error");
  if (errors) drawComplianceEl.classList.add("bad");
  const head = document.createElement("b");
  head.textContent = errors ? "Not compliant: " : "Note: ";
  drawComplianceEl.appendChild(head);
  drawComplianceEl.appendChild(document.createTextNode(issues.map((i) => i.message).join(" ")));
}

let drawPreviewTimer = 0;
let drawPreviewPending = false;
/** The Draw tab's formula, SMILES and checks, worked out once the drawing pauses (250 ms). */
function scheduleDrawPreview(preserveStatus: boolean): void {
  // A user's change clears the status NOW, as the immediate refresh did: the canvas sets its own message
  // ("Chain of 5 bonds drawn.") right after, and a clear 250 ms later would wipe it (review).
  if (!preserveStatus) setStatus("");
  // Insert is live at once on a page with something on it (Insert works the preview out first).
  insertBuildBtn.disabled = drawingEmpty();
  drawPreviewPending = true;
  window.clearTimeout(drawPreviewTimer);
  drawPreviewTimer = window.setTimeout(flushDrawPreview, 250);
}
/** Works out a waiting Draw preview now (before Insert or anything else that reads it). */
function flushDrawPreview(): void {
  window.clearTimeout(drawPreviewTimer);
  const pending = drawPreviewPending;
  drawPreviewPending = false;
  // Only while the Draw tab is the one shown: the Text tab's build is its own. The status was settled when
  // the change was scheduled.
  if (pending && buildTab === "draw") updateDrawPreview(true);
}

/**
 * Derives the insertable result from the drawn molecule — the same BuildResult
 * pipeline as the typed builder, so the preview below the canvas is exactly the
 * figure that will insert (the canvas itself is the editing view, not the
 * insert artifact).
 */

function updateDrawPreview(preserveStatus = false): void {
  // A direct refresh supersedes one waiting.
  window.clearTimeout(drawPreviewTimer);
  drawPreviewPending = false;
  currentBuild = null;
  currentBuildIonic = false;
  insertBuildBtn.disabled = true;
  const pageEmpty = drawingEmpty();
  const chem = drawEditor && !pageEmpty ? drawEditor.chemistry() : null;
  const mol = drawEditor ? (chem?.ok ? chem.mol : drawEditor.getMolecule()) : null;
  // What inserts from the Draw tab is the page as drawn; the preview shows it.
  const drawn = drawEditor && !pageEmpty ? drawEditor.render(false) : null;

  // Canvas editing is fluid — deleting an R1 atom to redraw it must not throw
  // away the definition the user typed for it, so R-group values persist
  // through every transient state of the drawing.
  keepRgroupValues = true;
  try {
    if (!pageEmpty && drawn && (!chem?.ok || !mol || mol.getAllAtoms() === 0)) {
      // A page whose structures have no single formula (or that has none): it inserts as drawn, and says why
      // there is no formula. (A page of structures with captions takes the structure path below: its
      // R-group legend, SMILES and compliance notes stay; it inserts as drawn.)
      buildFragmentToggle.checked = !!drawEditor?.isFragment();
      buildPreviewEl.innerHTML = drawn.svg;
      buildFormulaEl.textContent =
        chem && !chem.ok && chem.repeatUnit
          ? `(${formatFormula(chem.repeatUnit.formula)})ₙ per repeat unit (MW ${chem.repeatUnit.mw} g/mol per unit) — ${chem.reason}`
          : chem && !chem.ok ? `— (${chem.reason})` : "—";
      buildSmilesEl.textContent = "—";
      showBuildStereo(null);
      renderRgroupInputs([]);
      renderCompliance([]);
      insertBuildBtn.disabled = false;
      if (!preserveStatus) setStatus("");
      return;
    }
    if (!mol || mol.getAllAtoms() === 0) {
      // The box MIRRORS the molecule's fragment flag, so ticking it on an
      // empty canvas pre-arms Markush for the drawing about to happen (a real
      // user read the old snap-back-to-unchecked as "the box does not check").
      // Mirroring keeps the two from ever contradicting — the defect the old
      // behavior was guarding against.
      buildFragmentToggle.checked = !!mol && mol.isFragment();
      buildPreviewEl.replaceChildren();
      const hint = document.createElement("span");
      hint.className = "hint";
      hint.textContent =
        "Draw in the editor above as in ChemDraw — pick a tool on its toolbar, then click or drag. Or Open ChemDraw file… to edit a structure from a file.";
      buildPreviewEl.appendChild(hint);
      buildFormulaEl.textContent = "—";
      buildSmilesEl.textContent = "—";
      showBuildStereo(null);
      renderRgroupInputs([]);
      renderCompliance([]);
      if (!preserveStatus) setStatus("");
      return;
    }

    try {
      let result = resultFromMolecule(mol, STRUCTURE_W, STRUCTURE_H, { picture: !drawn });
      currentBuild = result;
      // Reflect the result, not just the flag: a drawn R-group makes the
      // structure generic even when the user never ticked the box.
      buildFragmentToggle.checked = result.generic;
      // The page as drawn is what inserts (the chemistry gives the formula, SMILES and alt text).
      if (drawn) currentBuild = result = { ...result, svg: drawn.svg };
      // η-bonded (a metallocene): the SMILES is the ionic form databases write, in Kekulé form as they write it
      // ([CH-]1C=CC=C1.…[Zr+4]) — labelled as a representation, not the bonding.
      const ionic = !!(chem?.ok && chem.ionic);
      currentBuildIonic = ionic;
      if (ionic) currentBuild = result = { ...result, smiles: (mol as unknown as { toIsomericSmiles(o: { kekulizedOutput: boolean }): string }).toIsomericSmiles({ kekulizedOutput: true }) };
      buildPreviewEl.innerHTML = result.svg;
      // The monoisotopic mass beside the average weight (⁹⁰Zr, ³⁵Cl…: what a mass spectrum's first peak sits at).
      const mono = (() => {
        if (!result.mw) return "";
        try {
          const c = compoundFromMolecule(mol);
          const m = "refusal" in c ? null : monoisotopicMass(c);
          return typeof m === "number" ? `; monoisotopic ${m.toFixed(4)}` : "";
        } catch {
          return "";
        }
      })();
      buildFormulaEl.textContent = formatFormula(result.formula) + (result.mw ? ` (MW ${result.mw} g/mol${mono})` : "");
      buildSmilesEl.textContent = result.smiles ? result.smiles + (ionic ? " (ionic representation)" : "") : "—";
      showBuildStereo(mol);
      renderRgroupInputs(result.rgroups);
      // The compliance note must never take the preview down with it.
      try {
        // The converter's own notes (a valence taken as drawn) beside OCL's.
        renderCompliance([...complianceIssues(mol), ...(chem?.ok ? chem.notes.map((m) => ({ kind: "valence" as const, severity: "note" as const, fixableByClean: false, message: m.charAt(0).toUpperCase() + m.slice(1) + "." })) : [])] as ComplianceIssue[]);
      } catch {
        renderCompliance([]);
      }
      insertBuildBtn.disabled = false;
      if (!preserveStatus) setStatus("");
    } catch (error) {
      buildFragmentToggle.checked = mol.isFragment();
      buildPreviewEl.replaceChildren();
      const hint = document.createElement("span");
      hint.className = "hint";
      hint.textContent = (error as Error).message;
      buildPreviewEl.appendChild(hint);
      buildFormulaEl.textContent = "—";
      buildSmilesEl.textContent = "—";
      showBuildStereo(null);
      renderRgroupInputs([]);
      renderCompliance([]);
    }
  } finally {
    keepRgroupValues = false;
  }
}

/**
 * Pops the drawing canvas out into a large Office dialog window — the same
 * editor at ~85% of the screen instead of 400px of pane. The current molecule
 * rides along in the URL (idcode + coordinates, the full-fidelity encoding);
 * "Use this drawing" in the dialog hands the result back the same way.
 */
/** The page as compact ChemDraw XML for the large canvas (no declaration, no indentation: more fits in a URL). */
function compactPage(): string {
  return writeCdxml(drawEditor!.page().root, true);
}

function openDrawDialog(molOnly?: string): void {
  if (!docHost.dialogsSupported()) {
    setStatus("This Word host does not support pop-out dialog windows.", "error");
    return;
  }
  const base = new URL("drawdialog.html", window.location.href).href;
  // The structure editor's drawing travels as its structure (idcode and layout): the window opens it in the same
  // ChemDraw-like editor. Only a ChemDraw page on the page canvas travels as a page.
  if (!molOnly && drawEditor && drawEditor === structureEditor) {
    const m = structureEditor.getMolecule();
    if (m.getAllAtoms()) {
      const enc = m.getIDCodeAndCoordinates();
      molOnly = `${enc.idCode} ${enc.coordinates}`;
    } else molOnly = "";
  }
  // The whole page travels — structures, brackets, arrows, text, group labels, as ChemDraw keeps them —
  // in the URL when short enough, else by message once the window says it is ready (as the CAD window does).
  flushDrawPreview();
  const hasPage = molOnly === undefined && !!drawEditor && drawEditor.page().objects.length > 0;
  const payload = hasPage ? JSON.stringify({ page: compactPage(), frag: drawEditor!.isFragment() || !!currentBuild?.generic }) : "";
  // In the URL the page goes as its own parameter (no JSON escaping: more fits); by message, as JSON.
  const inUrl = hasPage ? `${base}?frag=${drawEditor!.isFragment() || currentBuild?.generic ? 1 : 0}&page=${encodeURIComponent(compactPage())}` : base;
  // A Word that cannot message a window: one plain structure still goes, as its structure (the older way).
  const url = molOnly ? `${base}?mol=${encodeURIComponent(molOnly)}` : !hasPage ? base : inUrl.length < 1800 ? inUrl : `${base}?wait=1`;
  if (molOnly && url.length >= 1800) {
    setStatus("This structure is too large to carry into the large canvas — edit it here (drag the editor's bottom edge to make it taller).", "error");
    return;
  }
  openDrawDialogBtn.disabled = true;
  docHost.openDialog(url, { height: 75, width: 70 }, {
    failed: (error) => {
      openDrawDialogBtn.disabled = false;
      setStatus(`Could not open the large canvas: ${error?.message ?? "unknown error"}`, "error");
    },
    message: (arg, dialog) => {
      const msg = (arg as { message?: string }).message;
      let data: { ready?: boolean; needMol?: boolean; page?: unknown; frag?: unknown; mol?: string; mol3d?: Draw3dPayload; cancel?: boolean } = {};
      try {
        data = JSON.parse(msg ?? "{}");
      } catch {
        /* not ours: treated as a cancel below */
      }
      // The window could not take the page by message (an older Word): one plain structure still goes, as its
      // structure in the address — the window is opened again with it.
      const reopenWithStructure = (): void => {
        dialog.close();
        const chem = drawEditor?.chemistry();
        // Not an η-bonded page: its molecule is the ionic form, not the drawing (it would open as loose ions).
        const plain = !!drawEditor && !drawEditor.hasDrawing() && chem?.ok && !chem.ionic && chem.mol.getAllAtoms() > 0 && !drawEditor.page().objects.some((o) => o.items.some((it) => it.kind === "fragment" && it.v.nodes.some((nd) => nd.nodeType === "Unspecified" || nd.nodeType === "Nickname" || nd.nodeType === "Fragment")));
        if (plain && chem?.ok && !molOnly) {
          const enc = chem.mol.getIDCodeAndCoordinates();
          const seed = `${enc.idCode} ${enc.coordinates}`;
          if (`${base}?mol=${encodeURIComponent(seed)}`.length < 1800) {
            setStatus("This version of Word carries only a plain structure into the large canvas — opening it with the structure alone (its layout and labels as drawn are kept here until you bring it back).", "");
            // The window just closed: Word needs a moment before another opens. The button stays off till then.
            window.setTimeout(() => openDrawDialog(seed), 800);
            return;
          }
        }
        openDrawDialogBtn.disabled = false;
        setStatus("This drawing is too large to carry into the large canvas on this version of Word — edit it here (drag the canvas's corner to make it taller).", "error");
      };
      if (data.needMol) return reopenWithStructure();
      if (data.ready) {
        if (!dialog.messageChild(payload)) reopenWithStructure();
        return;
      }
      dialog.close();
      openDrawDialogBtn.disabled = false;
      if (data.cancel || !msg) return;
      if (data.mol3d) {
        void insertDraw3d(data.mol3d);
        return;
      }
      setBuildTab("draw");
      if (!drawEditor) return;
      try {
        if (data.mol && drawEditor === structureEditor) {
          // The structure editor takes the structure itself (idcode and layout): exact, as drawn in the window.
          const [idcode, coords] = data.mol.split(/\s+/);
          drawEditor.setMolecule(coords ? OclMolecule.fromIDCode(idcode, coords) : OclMolecule.fromIDCode(idcode));
        } else if (typeof data.page === "string") {
          const r = readCdxml(data.page);
          if (!r.ok) throw new Error(r.reason);
          // One edit in the pane: Undo returns to the page as it was before the large canvas.
          if (!drawEditor.replacePage(r.doc)) return;
          drawEditor.setFragment(data.frag === true);
        } else if (data.mol) {
          const [idcode, coords] = data.mol.split(/\s+/);
          drawEditor.setMolecule(coords ? OclMolecule.fromIDCode(idcode, coords) : OclMolecule.fromIDCode(idcode));
        } else return;
        updateDrawPreview();
        setStatus("Drawing brought back from the large canvas (Undo returns to the page as it was).", "success");
      } catch (error) {
        setStatus(`Could not read the drawing back: ${(error as Error).message}`, "error");
      }
    },
    // The user closing the dialog window (X) arrives here — re-arm the button.
    closed: () => {
      openDrawDialogBtn.disabled = false;
    },
  });
}

/**
 * "Draw a component" in Reaction mode: opens the large canvas blank; the
 * drawn structure comes back and lands AT THE CURSOR of the reaction input
 * as verified SMILES (reactionComponentSmiles round-trips it by idcode —
 * a scheme must never silently show a different molecule than was drawn).
 */
function openDrawForReaction(): void {
  if (!docHost.dialogsSupported()) {
    setStatus("This Word host does not support pop-out dialog windows.", "error");
    return;
  }
  const url = new URL("drawdialog.html", window.location.href).href;
  reactionDrawBtn.disabled = true;
  docHost.openDialog(url, { height: 75, width: 70 }, {
    failed: (error) => {
      reactionDrawBtn.disabled = false;
      setStatus(`Could not open the drawing canvas: ${error?.message ?? "unknown error"}`, "error");
    },
    message: (arg, dialog) => {
      dialog.close();
      reactionDrawBtn.disabled = false;
      const msg = (arg as { message?: string }).message;
      if (!msg) return;
      try {
        const data = JSON.parse(msg) as { page?: string; mol?: string; mol3d?: Draw3dPayload; cancel?: boolean };
        if (data.cancel) return;
        // Either button in the dialog identifies the molecule — "Use this
        // drawing" sends idcode+coords, "Insert 3D picture" sends the idcode.
        const idcode = data.mol ? data.mol.split(/\s+/)[0] : data.mol3d?.idcode;
        if (!idcode) {
          // A page that is not one readable structure (arrows, brackets, text, group labels, no single formula).
          if (data.page) setStatus("A reaction component is one structure — draw it without arrows, brackets, captions or group labels (OMe, Ph …), so its SMILES is exact.", "error");
          return;
        }
        const mol = OclMolecule.fromIDCode(idcode);
        const r = reactionComponentSmiles(mol);
        if (r.error || !r.smiles) {
          setStatus(r.error ?? "Could not read the drawing.", "error");
          return;
        }
        // TIER-0 GUARD (adversarial pass): if this SMILES collides with a
        // dictionary name/formula that resolves to a DIFFERENT structure,
        // the renderer would silently swap molecules — drawn methanol emits
        // "CO", and the formula table's CO is carbon monoxide. Mark such
        // components explicit; the renderer honors the prefix.
        let component = r.smiles;
        const asRendered = renderStructure(component, 80, 60);
        if (!asRendered || asRendered.idcode !== mol.getIDCode()) {
          component = `smiles:${component}`;
        }
        const el = reactionInput;
        const start = el.selectionStart ?? el.value.length;
        const end = el.selectionEnd ?? start;
        const before = el.value.slice(0, start);
        const after = el.value.slice(end);
        const needLeft = before !== "" && !/\s$/.test(before);
        const needRight = after !== "" && !/^\s/.test(after);
        const insert = `${needLeft ? " " : ""}${component}${needRight ? " " : ""}`;
        el.value = before + insert + after;
        const caret = before.length + insert.length;
        el.setSelectionRange(caret, caret);
        el.focus();
        updateReactionPreview();
        setStatus("Drawn structure added to the reaction as SMILES.", "success");
      } catch (error) {
        setStatus(`Could not read the drawing back: ${(error as Error).message}`, "error");
      }
    },
    closed: () => {
      reactionDrawBtn.disabled = false;
    },
  });
}

/** The 3D view the large canvas hands back: idcode + how the user oriented it. */
interface Draw3dPayload {
  idcode: string;
  style: Mol3dStyle;
  showH: boolean;
  showLabels?: boolean;
  rot: number[];
  zoom: number;
}

/**
 * Inserts the 3D model the large canvas composed. The conformer is REGENERATED
 * here from the idcode (fixed seed — identical coordinates to what the dialog
 * displayed), then rendered through the same projectScene/opsToSvg pair the
 * dialog's live view uses, in the exact orientation the user chose. What you
 * saw is what inserts.
 */
async function insertDraw3d(payload: Draw3dPayload): Promise<void> {
  setStatus("Generating 3D conformer for the figure…");
  // Let the status paint before the synchronous generation blocks the pane.
  await new Promise((resolve) => setTimeout(resolve, 30));
  try {
    const model = generate3d(payload.idcode);
    if (isMol3dError(model)) {
      setStatus(model.error, "error");
      return;
    }
    const W3D = 640, H3D = 480;
    const rotOk = Array.isArray(payload.rot) && payload.rot.length === 9 && payload.rot.every((v) => Number.isFinite(v));
    const view: Mol3dView = {
      rot: rotOk ? payload.rot : defaultMol3dView().rot,
      zoom: typeof payload.zoom === "number" && Number.isFinite(payload.zoom) && payload.zoom > 0 ? Math.min(5, payload.zoom) : 1,
      showH: payload.showH !== false,
      showLabels: payload.showLabels !== false,
      style: payload.style === "stick" || payload.style === "spacefill" ? payload.style : "ballstick",
    };
    const styleName = view.style === "ballstick" ? "ball-and-stick" : view.style === "spacefill" ? "space-filling" : "stick";
    // The scene projects into the band above the caption line, so the
    // molecule can never sit on its own caption.
    const ops = projectScene(model, view, W3D, H3D - 26);
    if (ops.length === 0) {
      // An all-hydrogen molecule with hydrogens hidden has nothing to show —
      // a blank white rectangle must never insert as if it were a figure.
      setStatus("Nothing visible to insert — every atom is hidden (hydrogens off).", "error");
      return;
    }
    const ionFormula = `${formulaSubscripts(model.formula)}${chargeSuperscript(model.netCharge)}`;
    const caption = `${ionFormula} — ${styleName}, MMFF94s conformer`;
    const svg = opsToSvg(ops, W3D, H3D, caption);
    const d = readSvgDims(svg, W3D, H3D);
    const base64 = await renderFigurePng(svg, d.w, d.h);
    const alt = provenanceAltText(
      `3D model (${styleName}, MMFF94s conformer) of ${ionFormula}`,
      ionFormula,
      0,
      "",
      payload.idcode,
    );
    await docHost.insertPictureAtSelection({
      base64: base64,
      widthPt: figurePoints(d.w / 2),
      heightPt: figurePoints(d.h / 2),
      alt: alt,
      selectAfter: true,
      tag: "formula-inserter:structure3d",
    });
    setStatus("3D model inserted.", "success");
    recordInsert("chemical", `3D ${model.formula}`, `3D ${model.formula}`);
  } catch (error) {
    setStatus(`Could not insert the 3D model: ${(error as Error).message}`, "error");
  }
}

/** Loads the Chemical-mode structure into the Draw canvas for modification. */
function openInDraw(): void {
  const s = currentStructure;
  if (!s) return;
  setMode("build");
  setBuildTab("draw");
  useStructureEditor();
  if (!drawEditor) return; // canvas unavailable — already fell back to Text
  try {
    // The ID code is the canonical structure (stereo and all); it carries no
    // 2D coordinates, so lay it out before handing it to the editor. A blank
    // idcode "parses" to an empty molecule, so fall through to SMILES on
    // empty as well as on error.
    let mol: OclMolecule | null = null;
    if (s.idcode) {
      try {
        mol = OclMolecule.fromIDCode(s.idcode);
      } catch {
        mol = null;
      }
    }
    if (!mol || mol.getAllAtoms() === 0) mol = OclMolecule.fromSmiles(s.smiles);
    if (mol.getAllAtoms() === 0) throw new Error("the structure is empty.");
    mol.inventCoordinates();
    drawEditor.setMolecule(mol);
    updateDrawPreview();
    // Show the canvas the structure went to: the pane was left scrolled to the bottom, the canvas out of sight.
    document.getElementById("build-editor")?.scrollIntoView({ block: "start" });
    setStatus("Structure loaded into the drawing canvas.", "success");
  } catch (error) {
    setStatus(`Could not load the structure into the canvas: ${(error as Error).message}`, "error");
  }
}

/** Builds a molecule from the Build textarea and shows its structure, formula, and SMILES. */
function updateBuildPreview(): void {
  // A Draw refresh still waiting does not apply to the Text tab.
  window.clearTimeout(drawPreviewTimer);
  drawPreviewPending = false;
  const text = buildInput.value;
  currentBuild = null;
  insertBuildBtn.disabled = true;

  if (!text.trim()) {
    buildPreviewEl.replaceChildren();
    const hint = document.createElement("span");
    hint.className = "hint";
    hint.textContent = "Type a name or a SMILES string, an atom / bond list, or paste a molfile to build a structure.";
    buildPreviewEl.appendChild(hint);
    buildFormulaEl.textContent = "—";
    buildSmilesEl.textContent = "—";
    showBuildStereo(null);
    renderRgroupInputs([]);
    setStatus("");
    return;
  }

  try {
    const format = buildFormatSelect.value as BuildFormat;
    const result = build(text, format, STRUCTURE_W, STRUCTURE_H);
    currentBuild = result;
    buildPreviewEl.innerHTML = result.svg;
    buildFormulaEl.textContent = formatFormula(result.formula) + (result.mw ? ` (MW ${result.mw} g/mol)` : "");
    buildSmilesEl.textContent = result.smiles || "—";
    try {
      showBuildStereo(result.idcode ? OclMolecule.fromIDCode(result.idcode) : null, true);
    } catch {
      showBuildStereo(null);
    }
    renderRgroupInputs(result.rgroups);
    insertBuildBtn.disabled = false;
    setStatus("");
  } catch (error) {
    buildPreviewEl.replaceChildren();
    const hint = document.createElement("span");
    hint.className = "hint";
    hint.textContent = (error as Error).message;
    buildPreviewEl.appendChild(hint);
    buildFormulaEl.textContent = "—";
    buildSmilesEl.textContent = "—";
    showBuildStereo(null);
    renderRgroupInputs([]);
  }
}

/** Builds one R-group definition row (main or nested sub-generic). */
function makeRgroupRow(label: string, isSub: boolean): HTMLElement {
  const row = document.createElement("div");
  row.className = isSub ? "rgroup-row rgroup-sub" : "rgroup-row";
  row.dataset.label = label;
  const lab = document.createElement("span");
  lab.className = "rgroup-label";
  lab.textContent = `${label} =`;
  const input = document.createElement("input");
  input.type = "text";
  input.className = "rgroup-input";
  input.placeholder = isSub
    ? "sub-group definition, e.g. halogen, hydroxy"
    : "e.g. H, C1-6 alkyl, opt sub phenyl, substituted with R1a, …";
  input.value = rgroupValues[label] || "";
  input.addEventListener("input", () => {
    rgroupValues[label] = input.value;
    syncSubGroups();
  });
  row.append(lab, input);
  return row;
}

/** Sub-generic R-group labels referenced (transitively) from the main definitions. */
function collectSubGroups(): string[] {
  const known: Record<string, true> = {};
  for (const l of mainRgroups) known[l] = true;
  const subs: string[] = [];
  let frontier = mainRgroups.slice();
  // Bounded depth guards against a definition that references itself in a cycle.
  for (let depth = 0; depth < 5 && frontier.length; depth++) {
    const next: string[] = [];
    for (const label of frontier) {
      for (const ref of referencedRGroups(rgroupValues[label] || "")) {
        if (!known[ref]) {
          known[ref] = true;
          subs.push(ref);
          next.push(ref);
        }
      }
    }
    frontier = next;
  }
  return subs;
}

/** Reconciles the sub-group input rows with the labels currently referenced,
 *  adding/removing rows in place so focus and caret are preserved while typing. */
function syncSubGroups(): void {
  if (!subGroupWrap) return;
  const subs = collectSubGroups();
  // Prune stored values that are neither a current main group nor a live
  // sub-group — but not during a transient refresh (mid-drawing states, tab
  // peeks), where deleting an R2 atom to reattach it must not erase the
  // definition the user typed for R2.
  if (!keepRgroupValues) {
    const valid: Record<string, true> = {};
    for (const l of mainRgroups) valid[l] = true;
    for (const l of subs) valid[l] = true;
    for (const key of Object.keys(rgroupValues)) {
      if (!valid[key]) delete rgroupValues[key];
    }
  }
  const existing: Record<string, HTMLElement> = {};
  for (const child of Array.from(subGroupWrap.children)) {
    const el = child as HTMLElement;
    if (el.dataset.label) existing[el.dataset.label] = el;
  }
  for (const label of Object.keys(existing)) {
    if (subs.indexOf(label) < 0) {
      subGroupWrap.removeChild(existing[label]);
      delete existing[label];
    }
  }
  for (const label of subs) {
    if (!existing[label]) subGroupWrap.appendChild(makeRgroupRow(label, true));
  }
}

/** Renders one definition input per R-group present in the built structure. */
function renderRgroupInputs(rgroups: string[]): void {
  buildRgroupsEl.replaceChildren();
  mainRgroups = rgroups.slice();
  subGroupWrap = null;
  if (!rgroups.length) {
    // No R-groups: drop every stored definition (sub-groups exist only via
    // mains) — unless this is a transient state a definition must survive.
    if (!keepRgroupValues) {
      for (const key of Object.keys(rgroupValues)) delete rgroupValues[key];
    }
    return;
  }
  // Drop values for main R-groups no longer present (keep referenced sub-groups).
  for (const label of rgroups) {
    buildRgroupsEl.appendChild(makeRgroupRow(label, false));
  }

  subGroupWrap = document.createElement("div");
  subGroupWrap.className = "rgroup-subs";
  buildRgroupsEl.appendChild(subGroupWrap);
  syncSubGroups();

  // Legend insertion format: an inline "where R1 = …" line or a structured table.
  const fmtRow = document.createElement("div");
  fmtRow.className = "legend-format";
  const fmtLab = document.createElement("span");
  fmtLab.className = "rgroup-label";
  fmtLab.textContent = "Insert as";
  fmtRow.appendChild(fmtLab);
  for (const [value, text] of [
    ["line", "Line"],
    ["table", "Table"],
  ] as const) {
    const id = `legend-fmt-${value}`;
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = "legend-format";
    radio.id = id;
    radio.checked = legendFormat === value;
    radio.addEventListener("change", () => {
      if (radio.checked) legendFormat = value;
    });
    const radioLab = document.createElement("label");
    radioLab.className = "legend-format-label";
    radioLab.htmlFor = id;
    radioLab.textContent = text;
    fmtRow.append(radio, radioLab);
  }
  buildRgroupsEl.appendChild(fmtRow);
}

/** Collects the current R-group definitions (main groups first, then nested
 *  sub-groups in reference order) as raw legend entries. */
function currentLegendEntries(): LegendEntry[] {
  const labels = [...mainRgroups, ...collectSubGroups()];
  return labels.map((label) => ({ label, definition: rgroupValues[label] || "" }));
}

/** Inserts the built molecule's structure as an inline picture, plus an R-group legend if defined. */
async function insertBuild(): Promise<void> {
  flushDrawPreview(); // the drawing as it is now, not as it was when it last paused
  // A drawn page with no structure as chemistry (arrows, text, labels with no exact form) inserts as drawn.
  // (Unless the preview just worked out refused it: Insert is live before the pause, the refusal stands — review.)
  if (!currentBuild && buildTab === "draw" && drawEditor?.page().objects.length) return insertBuildBtn.disabled ? undefined : insertDrawingOnly(false);
  const molecule = currentBuild;
  if (!molecule) {
    setStatus("Nothing built to insert.", "error");
    return;
  }

  // Capture the history record NOW, before the awaits below — the user can keep
  // drawing (or switch tabs) while the insert is in flight, and history must
  // store what was inserted, not what the surface holds a second later. A drawn
  // structure is recorded as `idcode: …` (OCL's canonical encoding with layout):
  // the ONE text form that round-trips the Markush/fragment flag and query
  // features — a molfile silently drops both.
  let recorded: string;
  if (buildTab === "draw" && drawEditor) {
    // Encode a copy carrying the same generic flag the derived result (and the
    // inserted provenance) carries — a drawn R-group forces generic even when
    // the live molecule's fragment bit was never ticked, and the recorded ID
    // code must name the structure that was actually inserted.
    const forRecord = drawEditor.getMolecule().getCompactCopy();
    if (molecule.generic) forRecord.setFragment(true);
    const enc = forRecord.getIDCodeAndCoordinates();
    recorded = `idcode: ${enc.idCode} ${enc.coordinates}`;
  } else {
    recorded = buildInput.value;
  }

  insertBuildBtn.disabled = true;
  setStatus("Inserting structure…");

  try {
    // From the Draw tab the picture is the page as drawn, at the chosen size (ChemDraw's or the USPTO's).
    let d = readSvgDims(molecule.svg, STRUCTURE_W, STRUCTURE_H);
    let sizeNote = "";
    if (buildTab === "draw" && drawEditor) {
      const r = drawEditor.render(false);
      if (r) {
        const size = canvasInsertSize(r, false);
        if (!size.ok) throw new Error(size.reason);
        d = { w: size.w, h: size.h };
        sizeNote = ` ${size.note}`;
      }
    }
    const base64 = await renderFigurePng(molecule.svg, d.w, d.h);
    const label = molecule.formula || "molecule";
    // The reopen code (OCL-ID) only for a page that is its structures: one with captions would reopen without them.
    const ionic = buildTab === "draw" && currentBuildIonic;
    const alt = ionic
      ? `Structure drawing (JurisLab) — ${molecule.formula}; SMILES ${molecule.smiles} (ionic representation: η-bonds have no SMILES)`
      : buildTab === "draw" && drawEditor?.hasDrawing()
        ? `Structure drawing (JurisLab) — ${molecule.formula}; SMILES ${molecule.smiles}`
        : provenanceAltText(`2D structure (${label})`, molecule.formula, molecule.mw, molecule.smiles, molecule.idcode);
    const entries = currentLegendEntries();
    const legendLine = buildLegendText(entries);
    const legendTable = legendFormat === "table" ? buildLegendTableHtml(entries) : "";
    const hasLegend = legendFormat === "table" ? !!legendTable : !!legendLine;
    await docHost.insertPictureWithLegend({
      base64,
      widthPt: figurePoints(d.w),
      heightPt: figurePoints(d.h),
      alt,
      legend:
        legendFormat === "table" && legendTable
          ? { kind: "table", html: legendTable }
          : legendLine
            ? { kind: "line", text: legendLine }
            : null,
      tag: "formula-inserter:structure",
    });
    const staleNow = buildTab === "draw" && drawEditor ? drawEditor.staleNames() : [];
    const warnNow = staleNow.length ? ` Check ${staleNow.map((w) => `“${w}”`).join(", ")}: ChemDraw computed ${staleNow.length === 1 ? "that name" : "those names"} before the structure changed.` : "";
    setStatus((hasLegend ? "Structure + R-group legend inserted." : "Structure inserted.") + sizeNote + warnNow, warnNow ? "" : "success");
    if (!ionic) recordInsert("build", recorded, label);
  } catch (error) {
    setStatus(`Could not insert structure: ${(error as Error).message}`, "error");
  } finally {
    insertBuildBtn.disabled = false;
  }
}

// ---------------------------------------------------------------------------
// Reference-numeral management
// ---------------------------------------------------------------------------

const NUMERALS_SETTING = "formula-inserter.numerals";

/** Loads the numeral table from this document's settings (best-effort). */
function loadNumerals(): void {
  try {
    const raw = docHost.getSetting(NUMERALS_SETTING) as string | null;
    const parsed = raw ? JSON.parse(raw) : [];
    numeralEntries = Array.isArray(parsed)
      ? parsed
          .filter((e) => e && Number.isFinite(e.numeral) && typeof e.element === "string")
          // A numeral past five digits (a damaged setting) loads as a cleared box, not as 2⁵³.
          .map((e) => ({ numeral: isValidNumeral(Math.floor(e.numeral)) ? Math.floor(e.numeral) : 0, element: e.element }))
      : [];
  } catch {
    numeralEntries = [];
  }
}

/** Persists the numeral table into this document's settings (best-effort). */
function saveNumerals(): void {
  try {
    docHost.setSetting(NUMERALS_SETTING, JSON.stringify(numeralEntries));
    docHost.saveSettings();
  } catch {
    // Settings unavailable (e.g. unsupported host) — table stays in memory only.
  }
}

/** Builds one editable numeral row: numeral input, element input, insert + remove. */
function makeNumeralRow(entry: NumeralEntry, idx: number): HTMLElement {
  const row = document.createElement("div");
  row.className = "num-row";

  const numInput = document.createElement("input");
  numInput.type = "number";
  numInput.min = "1";
  numInput.max = String(MAX_NUMERAL);
  numInput.className = "rgroup-input num-numeral";
  numInput.value = String(entry.numeral);
  numInput.setAttribute("aria-label", "Reference numeral (1 to 99999)");
  numInput.addEventListener("input", () => {
    // Digits only, 1 to 99999: parseInt("1e20") was 1 and 2⁵³ hung the next-numeral search.
    numeralEntries[idx].numeral = parseNumeralInput(numInput.value);
    saveNumerals();
  });

  const eltInput = document.createElement("input");
  eltInput.type = "text";
  eltInput.className = "rgroup-input";
  eltInput.placeholder = "element name, e.g. housing";
  eltInput.value = entry.element;
  eltInput.setAttribute("aria-label", "Element name");
  eltInput.addEventListener("input", () => {
    numeralEntries[idx].element = eltInput.value;
    saveNumerals();
  });

  const insertBtn = document.createElement("button");
  insertBtn.type = "button";
  insertBtn.className = "num-callout-btn";
  insertBtn.textContent = "Insert";
  insertBtn.title = "Insert this callout at the cursor";
  insertBtn.addEventListener("click", () => insertCallout(idx));

  const removeBtn = document.createElement("button");
  removeBtn.type = "button";
  removeBtn.className = "num-remove-btn";
  removeBtn.textContent = "×";
  removeBtn.title = "Remove this numeral";
  removeBtn.setAttribute("aria-label", "Remove numeral");
  removeBtn.addEventListener("click", () => {
    numeralEntries.splice(idx, 1);
    renderNumeralRows();
    saveNumerals();
  });

  row.append(numInput, eltInput, insertBtn, removeBtn);
  return row;
}

/** Re-renders all numeral rows from the in-memory table. */
function renderNumeralRows(): void {
  numListEl.replaceChildren();
  if (!numeralEntries.length) {
    const hint = document.createElement("span");
    hint.className = "hint";
    hint.textContent = "No reference numerals yet. Add one to start the table.";
    numListEl.appendChild(hint);
    return;
  }
  numeralEntries.forEach((entry, idx) => numListEl.appendChild(makeNumeralRow(entry, idx)));
}

/** Appends a new numeral row with a suggested next number and focuses it. */
function addNumeral(): void {
  numeralEntries.push({ numeral: suggestNextNumeral(numeralEntries), element: "" });
  renderNumeralRows();
  saveNumerals();
  const last = numListEl.querySelector<HTMLInputElement>(".num-row:last-child .rgroup-input:not(.num-numeral)");
  last?.focus();
}

/** Inserts a single "element (numeral)" callout at the selection. */
async function insertCallout(idx: number): Promise<void> {
  const entry = numeralEntries[idx];
  if (!entry || !entry.numeral) {
    setStatus("Give this row a numeral first.", "error");
    return;
  }
  const text = formatCallout(entry.element, entry.numeral, numParensCheckbox.checked);
  try {
    await docHost.insertAtSelection({
      kind: "text",
      content: text,
      at: "replace",
      select: "inserted",
      tag: `formula-inserter:callout:${entry.numeral}`,
    });
    setStatus(`Inserted “${text}”.`, "success");
  } catch (error) {
    setStatus(`Could not insert callout: ${(error as Error).message}`, "error");
  }
}

/** Reads the document body, reconciles it with the table, and shows findings. */
async function scanDocumentNumerals(): Promise<void> {
  numScanBtn.disabled = true;
  setStatus("Scanning document…");
  try {
    const bodyText = await docHost.readBodyText();
    // The table bounds what counts as a callout: a citation year or a
    // list marker far outside the numbering range is not one.
    const docNumerals = extractNumerals(bodyText, numeralEntries.map((e) => e.numeral));
    renderNumeralFindings(reconcileNumerals(numeralEntries, docNumerals, bodyText), docNumerals.length);
    setStatus("Scan complete.", "success");
  } catch (error) {
    setStatus(`Could not scan the document: ${(error as Error).message}`, "error");
  } finally {
    numScanBtn.disabled = false;
  }
}

/** Renders the reconciliation report into the findings panel. */
function renderNumeralFindings(
  findings: ReturnType<typeof reconcileNumerals>,
  calloutCount: number,
): void {
  numFindingsEl.classList.remove("ok", "error");
  if (findings.ok) {
    numFindingsEl.classList.add("ok");
    numFindingsEl.textContent = `✓ No issues. ${calloutCount} parenthesized callout${
      calloutCount === 1 ? "" : "s"
    } found, all consistent with the table.`;
    return;
  }
  const items: string[] = [];
  for (const c of findings.collisions) {
    items.push(`Numeral (${c.numeral}) is reused for: ${c.elements.map(esc).join(", ")}`);
  }
  // THE INVERSE CHECK, and the more common real drafting defect: one element
  // given two different numerals — "housing (12)" in one place and
  // "housing (14)" in another. Without this branch a duplicates-only report
  // rendered "0 issues found" in red with an empty list, because `ok` was
  // already false.
  for (const d of findings.duplicates) {
    items.push(
      `“${esc(d.element)}” is given more than one numeral: ${d.numerals.map((n) => `(${n})`).join(", ")}` +
        " — if these are different parts, name them apart (e.g. “first housing” / “second housing”).",
    );
  }
  if (findings.gaps.length) {
    items.push(`Skipped numeral${findings.gaps.length === 1 ? "" : "s"}: ${findings.gaps.join(", ")}`);
  }
  if (findings.orphans.length) {
    items.push(
      `Called out but not defined: ${findings.orphans.map((n) => `(${n})`).join(", ")}`,
    );
  }
  if (findings.unused.length) {
    items.push(
      `Defined but never called out: ${findings.unused
        .map((e) => `(${e.numeral})${e.element ? " " + esc(e.element) : ""}`)
        .join(", ")}`,
    );
  }
  numFindingsEl.classList.add("error");
  numFindingsEl.innerHTML =
    `<strong>${items.length} issue${items.length === 1 ? "" : "s"} found</strong>` +
    `<ul>${items.map((t) => `<li>${t}</li>`).join("")}</ul>`;
}

/** Inserts a "List of Reference Numerals" heading + table at the selection. */
async function insertNumeralList(): Promise<void> {
  const html = buildNumeralListHtml(numeralEntries);
  if (!html) {
    setStatus("Define at least one numeral (with an element name) first.", "error");
    return;
  }
  numInsertListBtn.disabled = true;
  setStatus("Inserting list…");
  try {
    await docHost.insertHeadedBlockBefore({ heading: NUMERAL_LIST_HEADING, html, tag: "formula-inserter:numeral-list" });
    setStatus("List of Reference Numerals inserted.", "success");
  } catch (error) {
    setStatus(`Could not insert the list: ${(error as Error).message}`, "error");
  } finally {
    numInsertListBtn.disabled = false;
  }
}

/**
 * Runs `fn` only after `ms` of quiet. For handlers whose work is superlinear in
 * the input, where recomputing per keystroke is not merely wasteful but can
 * exceed the time a task pane may block for.
 *
 * Deliberately NOT applied wholesale to the other input handlers: most of them
 * are cheap, and a delayed readout on a cheap calculation reads as lag. Use it
 * where the cost is real.
 */
function debounce<T extends unknown[]>(fn: (...args: T) => void, ms: number): (...args: T) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (...args: T) => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      fn(...args);
    }, ms);
  };
}

/**
 * Release D: Stats and Solve recompute after a pause in typing (measured up to ~0.2 s per keystroke on 2000 values
 * or a hard integral; lib/previewDebounce.ts). Insert FLUSHES first, so it never inserts an earlier keystroke's result.
 */
const statsPreview = debouncedPreview(() => updateStatsPreview());
const solvePreview = debouncedPreview(() => updateSolve());
/**
 * E1 fix: Finance recomputes after a pause when the keystroke is in a block (multi-line table) field: a 10,000-row
 * damages table costs a few hundred ms per run. Number fields stay live; Insert and the panel tray flush first.
 */
const finPreview = debouncedPreview(() => updateFinancePreview(), FIN_BLOCK_DEBOUNCE_MS);

/** Minimal HTML escape for findings text. */
function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

// ---------------------------------------------------------------------------
// DNA / RNA analysis
// ---------------------------------------------------------------------------

/** Recomputes the live DNA readouts (stats, strands, translation) from the input. */
function updateDnaPreview(): void {
  const { seq, invalid, records } = cleanDna(dnaInput.value);

  if (!seq) {
    dnaReadout.textContent = invalid.length ? `Ignored invalid: ${invalid.join(" ")}` : "";
    dnaStats.replaceChildren();
    dnaRevcompEl.textContent = "";
    dnaMrnaEl.textContent = "";
    dnaProteinEl.textContent = "";
    dnaCodeNoteEl.textContent = "";
    dnaTm.textContent = "";
    dnaProteinProps.textContent = "";
    dnaRevcompInsert.disabled = true;
    dnaMrnaInsert.disabled = true;
    dnaProteinInsert.disabled = true;
    return;
  }

  const stats = baseStats(seq);
  // A multi-record paste is concatenated, which is almost never what the user
  // meant — say so rather than analysing a chimera in silence.
  const multi = records > 1 ? ` · ⚠ ${records} FASTA records were joined — analyse one at a time` : "";
  dnaReadout.textContent =
    `${stats.length} nt${invalid.length ? ` · ignored invalid: ${invalid.join(" ")}` : ""}${multi}`;
  dnaStats.innerHTML =
    `<span><strong>GC:</strong> ${stats.gcPercent.toFixed(1)}%</span>` +
    `<span><strong>A</strong> ${stats.a} · <strong>C</strong> ${stats.c} · <strong>G</strong> ${stats.g} · <strong>T/U</strong> ${stats.t}` +
    `${stats.other ? ` · <strong>other</strong> ${stats.other}` : ""}</span>`;

  dnaRevcompEl.textContent = reverseComplement(seq);
  dnaMrnaEl.textContent = transcribe(seq);

  // Translation honors the chosen frame; negative frames use the reverse strand.
  const raw = parseInt(dnaFrameSelect.value, 10);
  const reverse = raw < 0;
  const frame = (Math.abs(raw) as 1 | 2 | 3) || 1;
  const source = reverse ? reverseComplement(seq) : seq;
  // v2.137.0: the NCBI genetic code is chosen, never assumed beyond table 1.
  // The report's notes are the sentences the output must carry — which table
  // was used (whenever it is not 1) and, for 27/28/31, that context-dependent
  // stops are read as sense. They go BESIDE the protein, not into it, so
  // "Insert protein" still inserts only residues.
  const table = parseInt(dnaTableSelect.value, 10) || 1;
  const report = translateReport(source, { frame, stopAtStop: dnaStopCheckbox.checked, table });
  const protein = report.protein;
  dnaProteinEl.textContent = protein || "(no residues in this frame)";
  const diffs = table === 1 ? [] : differencesFromStandard(table);
  dnaCodeNoteEl.textContent = [
    ...report.notes,
    ...(diffs.length ? [`Differs from the standard code at ${diffs.join(", ")}.`] : table === 1 ? [] : ["Same codon assignments as the standard code (start codons differ)."]),
  ].join(" ");

  // Tools readouts: primer Tm of the input, and properties of the translated protein.
  const tm = primerTm(seq);
  // The conditions are part of the number. A Tm quoted without its salt and primer
  // concentration is not a fact about the oligo — it moves ~10 °C between 10 mM and
  // 1 M Na⁺, and different suppliers' calculators assume different defaults, which
  // is exactly why two people "get different Tm" for the same primer.
  //
  // A REFUSAL IS NOT A NUMBER. Too many ambiguity codes and there is no honest
  // Tm to quote — every skipped nearest-neighbour step costs roughly 2 °C, so a
  // heavily degenerate primer reads tens of degrees low. `tm.tm` is 0 in that
  // case and must not be shown as though it were a measurement.
  const tmHead = tm.refusal
    ? `Primer Tm: ${tm.refusal}`
    : `Primer Tm ≈ ${tm.tm.toFixed(1)} °C · ${tm.gcPercent.toFixed(0)}% GC · ${tm.length} nt` +
      (tm.method === "nearest-neighbour" ? " · nearest-neighbour, 50 mM Na⁺, 0.25 µM" : " · Wallace rule (too short for NN)") +
      (tm.ambiguous ? ` · ${tm.ambiguous} ambiguity code${tm.ambiguous === 1 ? "" : "s"}` : "");
  // The caveats exist precisely for the degenerate and short-oligo cases, and
  // nothing was showing them. Same element rather than a new one: an added id
  // has to be wired, and this readout is already the place a user looks.
  dnaTm.textContent = tm.caveats.length ? `${tmHead}\n${tm.caveats.join(" ")}` : tmHead;
  const props = proteinProperties(protein);
  dnaProteinProps.textContent = props.length
    ? `Protein (this frame): ${props.length} aa · MW ${props.mw.toLocaleString("en-US")} Da · pI ${props.pI} · GRAVY ${props.gravy.toFixed(2)}` +
      // Residues with no tabulated mass are skipped by proteinProperties. Saying
      // so is the difference between "16 aa" and "16 of the 20 you pasted" —
      // translate() emits X for any codon a degenerate base leaves unresolved,
      // so this is common rather than exotic.
      (props.skippedCount
        ? ` · ${props.skippedCount} of ${props.inputLength} residue${props.inputLength === 1 ? "" : "s"} skipped (${props.skipped.join(", ")})`
        : "") +
      // INTERNAL stops only. A trailing "*" is the normal end of a CDS; an
      // internal one means this frame is not a single open reading frame, which
      // is the thing worth saying. Reporting a terminal stop as a problem would
      // be a false alarm on correct input.
      (props.internalStops
        ? ` · ${props.internalStops} internal stop codon${props.internalStops === 1 ? "" : "s"}: this frame is not a single ORF`
        : "")
    : "";

  dnaRevcompInsert.disabled = false;
  dnaMrnaInsert.disabled = false;
  dnaProteinInsert.disabled = !protein;
}

/** Scans the sequence for common restriction sites and renders them. */
function findRestrictionSites(): void {
  const { seq } = cleanDna(dnaInput.value);
  if (!seq) {
    setStatus("Enter a DNA sequence first.", "error");
    return;
  }
  const raw = findSites(seq);
  if (!raw.length) {
    dnaRestrictResults.innerHTML = '<span class="hint">No restriction sites found.</span>';
    return;
  }
  const hits = summarise(raw);
  const unique = new Set(uniqueCutters(raw));
  const cell = 'style="border:1px solid #000;padding:2px 8px;"';
  const rows = hits
    .map((h) => {
      const e = ENZYMES.find((x) => x.name === h.enzyme);
      const site = e ? formatSite(e) : h.site;
      // A unique cutter is the one you can actually clone into — flag it.
      const tag = unique.has(h.enzyme) ? " ★" : "";
      const oh = h.overhang === "blunt" ? "blunt" : `${h.overhang} overhang`;
      return `<tr><td ${cell}>${esc(h.enzyme)}${tag}</td><td ${cell}>${esc(site)}</td><td ${cell}>${oh}</td><td ${cell}>${h.positions.join(", ")}</td></tr>`;
    })
    .join("");
  dnaRestrictResults.innerHTML =
    '<table style="border-collapse:collapse;"><tr>' +
    `<td ${cell}><strong>Enzyme</strong></td><td ${cell}><strong>Site</strong></td><td ${cell}><strong>Ends</strong></td><td ${cell}><strong>Positions</strong></td></tr>` +
    rows +
    "</table>" +
    `<div class="hint" style="margin-top:6px">★ = cuts once (a unique cutter). Both strands are searched, so asymmetric sites (BsaI, BsmBI, BbsI) are found on either.</div>`;

  // Methylation is the difference between this prediction and the gel. MboI on
  // plasmid DNA from an ordinary dam+ strain cuts NOTHING, and DpnI cuts ONLY
  // methylated DNA — neither failure announces itself, you just lose a week. The
  // table above cannot show that, so it goes underneath in full.
  const methWarnings = methylationWarnings(seq, raw);
  if (methWarnings.length) {
    const seen = new Set<string>();
    const unique2: string[] = [];
    for (const w of methWarnings) {
      // One line per enzyme+methylase; the position is already in the message.
      const key = `${w.enzyme}:${w.methylase}:${w.effect}`;
      if (seen.has(key)) continue;
      seen.add(key);
      unique2.push(w.message);
    }
    dnaRestrictResults.appendChild(specCaveats(unique2));
  }
  setStatus(
    `Found ${hits.length} enzyme${hits.length === 1 ? "" : "s"}; ${unique.size} cut${unique.size === 1 ? "s" : ""} once.`,
    "success"
  );
}

/**
 * Puts the pane in the right theme.
 *
 * Word is asked first because the pane lives inside Word: running Word in Black
 * on a light desktop should give a dark pane, not a white slab bolted to a black
 * application. `Office.context.officeTheme` is not present on every host or
 * build, so it is read defensively and a missing value falls through to the OS.
 */
function applyTheme(): void {
  const officeTheme = (Office as unknown as { context?: { officeTheme?: { bodyBackgroundColor?: string } } })
    ?.context?.officeTheme;
  const { attribute } = resolveTheme({
    pref: getPrefs().theme,
    host: hostTheme(officeTheme),
    osPrefersDark:
      typeof window.matchMedia === "function" && window.matchMedia("(prefers-color-scheme: dark)").matches,
  });
  const root = document.documentElement;
  if (attribute) root.setAttribute("data-theme", attribute);
  // No attribute = let the media query decide, so an OS change needs no listener.
  else root.removeAttribute("data-theme");
}

/** Cuts the sequence with the chosen enzymes and reports the fragments. */
function runVirtualDigest(): void {
  currentDigestText = "";
  digestInsertBtn.disabled = true;
  const { seq } = cleanDna(dnaInput.value);
  if (!seq) {
    digestResults.innerHTML = '<span class="hint">Enter a DNA sequence first.</span>';
    return;
  }

  const wanted = digestEnzymes.value
    .split(/[\s,;]+/)
    .map((t) => t.trim())
    .filter(Boolean);

  // An enzyme the user asked for that this tool does not know is worth saying
  // out loud: silently digesting with the OTHER enzymes would produce a
  // plausible fragment list for a digest they did not request.
  const known = new Set(ENZYMES.map((e) => e.name.toLowerCase()));
  const unknown = wanted.filter((w) => !known.has(w.toLowerCase()));
  const only = wanted
    .filter((w) => known.has(w.toLowerCase()))
    .map((w) => ENZYMES.find((e) => e.name.toLowerCase() === w.toLowerCase())!.name);

  if (wanted.length && !only.length) {
    digestResults.innerHTML = `<span class="hint">None of those enzymes are in the table (${esc(unknown.join(", "))}). Leave the box blank to use every enzyme that cuts.</span>`;
    return;
  }

  const circular = digestTopology.value === "circular";
  const hits = findSites(seq, { circular, ...(only.length ? { only } : {}) });
  const result = digest(seq.length, hits, circular);
  const bands = gelBands(result.sizes);

  const cell = 'style="border:1px solid #000;padding:2px 8px;"';
  const rows = result.fragments
    .map((f, i) => {
      const ends = `${f.leftEnzyme ?? "end"} / ${f.rightEnzyme ?? "end"}`;
      const span = f.spansOrigin ? `${f.start}\u2013${f.end} (through origin)` : `${f.start}\u2013${f.end}`;
      return `<tr><td ${cell}>${i + 1}</td><td ${cell}>${f.length}</td><td ${cell}>${esc(span)}</td><td ${cell}>${esc(ends)}</td></tr>`;
    })
    .join("");

  const text = describeDigest(result);
  digestResults.innerHTML =
    (result.uncut
      ? `<span class="hint">${esc(text)}</span>`
      : '<table style="border-collapse:collapse;"><tr>' +
        `<td ${cell}><strong>#</strong></td><td ${cell}><strong>bp</strong></td><td ${cell}><strong>Span</strong></td><td ${cell}><strong>Ends</strong></td></tr>` +
        rows +
        "</table>" +
        `<div class="hint" style="margin-top:6px">${esc(text.split("\n").slice(1).join(" \u00b7 "))}</div>`) +
    (unknown.length
      ? `<div class="hint" style="margin-top:4px">\u26a0 Not in the enzyme table, so not used: ${esc(unknown.join(", "))}.</div>`
      : "");

  currentDigestText = text;
  digestInsertBtn.disabled = result.uncut;
  setStatus(
    result.uncut
      ? "Not cut by those enzymes."
      : `${result.fragments.length} fragment${result.fragments.length === 1 ? "" : "s"}, ${bands.length} band${bands.length === 1 ? "" : "s"} on a gel.`,
    result.uncut ? "error" : "success",
  );
}

/** Inserts a plain-text result at the cursor. Shared by ~14 tools, not just DNA. */
// Re-entrancy guard shared by every text-insert button (MS, Stats, Assay, DNA,
// Finance…): a fast double-click would otherwise queue two insertions of the
// same text before the first Word.run resolves.
/**
 * Inserts an alignment as MONOSPACE text.
 *
 * insertText() inherits the document's font, which is proportional in every
 * default Word template. An alignment is a column-wise claim — the ruler's '|'
 * must sit directly above the residues it refers to — and a proportional font
 * silently breaks that correspondence while still looking like an alignment. That
 * is a wrong figure, not an ugly one, so this goes in via insertHtml with an
 * explicit monospace family and the whitespace preserved.
 */
async function insertAlignmentText(): Promise<void> {
  if (!currentAlignText.trim()) {
    setStatus("Nothing to insert — align two sequences first.", "error");
    return;
  }
  // Not a bare return — see insertResultBlocks. A silent refusal is
  // indistinguishable from a dead button.
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return;
  }
  insertTextBusy = true;
  try {
    const html =
      `<pre style="font-family:Consolas,'Courier New',monospace;font-size:9pt;` +
      `white-space:pre;margin:0">${esc(currentAlignText)}</pre>`;
    await docHost.insertAtSelection({ kind: "html", content: html, at: "replace", select: "selection" });
    setStatus("Alignment inserted.", "success");
  } catch (e) {
    setStatus(`Could not insert the alignment: ${(e as Error).message}`, "error");
  } finally {
    insertTextBusy = false;
  }
}

let insertTextBusy = false;

/**
 * Runs a composite "text AND figure" insert under a guard that spans BOTH
 * halves, and disables its button while it runs.
 *
 * WHY `insertTextBusy` IS NOT ENOUGH, and why four comments in this file said
 * otherwise until an adversarial pass measured it. `insertPlainText` releases
 * that flag in its own `finally` — which fires when the TEXT is done, before
 * the caller has rasterised anything. The figure phase then runs
 * `renderFigurePng`, tens of milliseconds of canvas work, with the flag CLEAR.
 * A second click in that window sails through the guard, inserts the text
 * again, and the two figures land after both texts:
 *
 *     text1, text2, fig1, fig2
 *
 * — every figure divorced from the result it belongs to. For an amortisation
 * split or a Q-Q plot that is a wrong document, not an untidy one.
 *
 * The guard is separate from `insertTextBusy` rather than an extension of it,
 * because the two answer different questions: that one protects a single Word
 * batch from re-entry, this one protects a multi-batch USER ACTION. Disabling
 * the button as well is what makes the state visible instead of merely safe.
 */
let compositeInsertBusy = false;
async function runCompositeInsert(btn: HTMLButtonElement, fn: () => Promise<void>): Promise<void> {
  if (compositeInsertBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return;
  }
  compositeInsertBusy = true;
  const wasDisabled = btn.disabled;
  btn.disabled = true;
  try {
    await fn();
  } finally {
    compositeInsertBusy = false;
    // Restore rather than force-enable: the result may legitimately have become
    // un-insertable while this ran (the user can type in the pane during it).
    btn.disabled = wasDisabled;
  }
}

/**
 * Returns TRUE only if the text actually reached the document.
 *
 * It used to return `void` while catching its own errors, which made every
 * caller that wanted to do something afterwards guess. Two of them guessed
 * wrong: the Stats and Bio/Assay "insert the result AND its figure" handlers
 * both carried a comment saying "only if the text went in — insertPlainText
 * reports its own failure", and neither could tell. A failed text insert still
 * appended the picture, and the handler then overwrote the error message with
 * "Result and chart inserted."
 *
 * The busy branch matters just as much: a second click returns false, so the
 * caller stops instead of falling through and inserting the FIGURE a second
 * time beside one copy of the text.
 */
async function insertPlainText(text: string, label: string, caretAfterText = false): Promise<boolean> {
  if (!text.trim()) {
    setStatus(`Nothing to insert for ${label.toLowerCase()}.`, "error");
    return false;
  }
  if (insertTextBusy) {
    // Was a silent `return`, so a second click looked like nothing happened.
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  try {
    // AFTER, not replace. This is the insert path for mass spec, spectra,
    // properties, stats, finance, assay, solve, analyze, cross-references and
    // SEQ ID refs, and it used to overwrite whatever the user had selected —
    // every other insert in the product appends. Losing a selected word to a
    // button labelled "Insert" is not a trade anyone agreed to.
    //
    // caretAfterText (v2.193.0): a FIGURE follows this text in a second batch (Statistics, Finance, Bio/Assay), and
    // that batch inserts after the selection. With the caret left on the original selection — which is BEFORE the
    // text just inserted after it — the figure landed ABOVE its own result. Those callers put the caret at the end
    // of the inserted text instead.
    await docHost.insertAtSelection({ kind: "text", content: text, at: "after", select: caretAfterText ? "inserted" : "selection" });
    setStatus(`${label} inserted. Ctrl/⌘+Z undoes it.`, "success");
    return true;
  } catch (error) {
    setStatus(`Could not insert ${label.toLowerCase()}: ${(error as Error).message}`, "error");
    return false;
  } finally {
    insertTextBusy = false;
  }
}

/** The Solid form tool's figure: through the pane's figure styles (USPTO, journals) like every plot. */
async function insertSolidFigure(o: { svg: string; render: (w: number) => string; alt: string; chartKind: string }): Promise<string> {
  return await insertFigure({ svg: o.svg, fallbackW: SOLID_CHART_SIZE.width, fallbackH: SOLID_CHART_SIZE.height, alt: o.alt, tag: "formula-inserter:solidform", render: o.render, chartKind: o.chartKind });
}

/**
 * The Diagrams tool's insert: the figure's own SVG rasterised at its natural size (sized in px = pt × 96/72 by the
 * engine), so the lettering keeps the height the engine drew it at (≥ 1/8 in, 1.84(p)(3)).
 */
async function insertDiagramPicture(svg: string, widthPt: number, heightPt: number, alt: string): Promise<boolean> {
  const w = (widthPt * 96) / 72, h = (heightPt * 96) / 72;
  try {
    const base64 = await renderFigurePng(svg, w, h);
    await docHost.insertPictureAtSelection({ base64, widthPt: figurePoints(w), heightPt: figurePoints(h), alt, selectAfter: true, tag: "formula-inserter:diagram" });
    return true;
  } catch (error) {
    setStatus(`Could not insert the diagram: ${(error as Error).message}`, "error");
    return false;
  }
}

/**
 * Formatted text (an OOXML package of runs: italics, sub/superscripts) after the selection —
 * the Characterization tool's insert. Same busy guard and status wording as insertPlainText.
 */
async function insertRunsText(ooxml: string, label: string): Promise<boolean> {
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  try {
    // A paragraph of its own (fix2-plat): at the end of a heading it became part of the heading.
    await docHost.insertAtSelection({ kind: "ooxml", content: ooxml, at: "after", select: "selection", ownParagraph: true });
    setStatus(`${label} inserted. Ctrl/⌘+Z undoes it.`, "success");
    return true;
  } catch (error) {
    setStatus(`Could not insert ${label.toLowerCase()}: ${(error as Error).message}`, "error");
    return false;
  } finally {
    insertTextBusy = false;
  }
}

/**
 * Inserts a worked derivation as REAL Word equations (OMML) rather than flat
 * ASCII. Falls back to the plain-text path if the host rejects the OOXML, so
 * the button always does something.
 */
async function insertDerivation(blocks: DerivationBlock[], plain: string, label: string): Promise<boolean> {
  if (!blocks.length) {
    setStatus(`Nothing to insert for ${label.toLowerCase()}.`, "error");
    return false;
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  try {
    const ooxml = buildDerivationOoxml(blocks);
    // AFTER, matching every other insert path — never overwrite a selection.
    await docHost.insertAtSelection({ kind: "ooxml", content: ooxml, at: "after", select: "selection", tag: "formula-inserter:solution" });
    // "more than once": the content flushes, then tagInserted() commits the
    // tracking content control in a SECOND flush, so one Ctrl+Z strips the tag
    // and leaves the equations behind. Promising single-step undo was wrong.
    setStatus(`${label} inserted as editable equations. Ctrl/⌘+Z undoes it — press it more than once.`, "success");
    return true;
  } catch (error) {
    // OOXML refused by the host — the derivation is still worth having as text.
    // The fallback's own verdict is the answer: if the text did not land
    // either, the caller must not go on to append a figure to nothing.
    insertTextBusy = false;
    return await insertPlainText(plain, label);
  } finally {
    insertTextBusy = false;
  }
}

/**
 * Inserts the current Solve result: the typeset derivation, plus the figure
 * when there is one (the persistence barcode). The figure is rasterised BEFORE
 * entering Word.run, because that conversion is async and Word.run batches.
 */
async function insertSolveResult(): Promise<void> {
  // ONLY IF THE DERIVATION LANDED (a figure is never appended to nothing), and
  // since v2.193.0 IN ONE PACKAGE: the derivation and its figure were two
  // batches, the figure inserted after a selection the derivation batch had left
  // BEFORE the derivation, so it could land above the text it illustrates.
  if (!currentSolveSvg) {
    await insertDerivation(currentSolveBlocks, currentSolveText, "solution");
    return;
  }
  // The caption the producing branch set, never a hardcoded one: Solve
  // draws four different figures through this single path.
  await insertDerivationWithFigure(currentSolveBlocks, currentSolveText, "solution", {
    svg: currentSolveSvg,
    fallbackW: 460,
    fallbackH: 300,
    alt: currentSolveAlt || "Figure for the solution above.",
    done: "Solution and figure inserted.",
  });
}

/**
 * A derivation (prose and equations) and the figure under it as ONE flat-OPC package (resultOoxml.ts), so the
 * figure cannot land anywhere but after the text, and Word's own picture count is checked. The figure is rasterised
 * FIRST, before anything enters Word: if it will not render, or Word refuses the package, the derivation goes in
 * alone through insertDerivation (still typeset equations; plain text only if Word refuses those too) and the status
 * says the figure did not. Resolves true when the text landed.
 */
async function insertDerivationWithFigure(
  blocks: DerivationBlock[],
  plain: string,
  label: string,
  fig: { svg: string; fallbackW: number; fallbackH: number; alt: string; done: string },
): Promise<boolean> {
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  const { w, h } = readSvgDims(fig.svg, fig.fallbackW, fig.fallbackH);
  let png: string;
  try {
    png = await renderFigurePng(fig.svg, w, h);
  } catch (error) {
    const ok = await insertDerivation(blocks, plain, label);
    if (ok) setStatus(`${label[0].toUpperCase()}${label.slice(1)} inserted, but the figure could not be drawn: ${(error as Error).message}`, "error");
    return ok;
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  let why = "";
  try {
    const built = buildResultOoxml([
      { kind: "xml", content: packageBodyXml(buildDerivationOoxml(blocks)) },
      { kind: "picture", caption: "", base64: png, widthPt: figurePoints(w), heightPt: figurePoints(h), alt: fig.alt },
    ]);
    const kept = await docHost.insertResultLayout([{ kind: "ooxml", ooxml: built.ooxml }]);
    if (kept !== null && kept < built.pictures) {
      setStatus(`${label[0].toUpperCase()}${label.slice(1)} inserted, but ${pictureNotKeptText(png.length)}`, "error");
      return true;
    }
    setStatus(`${fig.done} Ctrl/⌘+Z undoes it.`, "success");
    return true;
  } catch (error) {
    why = (error as Error).message;
  } finally {
    insertTextBusy = false;
  }
  // The package was refused: the derivation alone (typeset), and say the figure is missing.
  const ok = await insertDerivation(blocks, plain, label);
  if (ok) setStatus(`${label[0].toUpperCase()}${label.slice(1)} inserted, but the figure could not be: ${why}`, "error");
  return ok;
}

/** Runs the six-frame ORF finder and renders the results table. */
function findOrfsHandler(): void {
  const { seq } = cleanDna(dnaInput.value);
  if (!seq) {
    setStatus("Enter a DNA/RNA sequence first.", "error");
    return;
  }
  const minAa = Math.max(1, parseInt(dnaOrfMin.value, 10) || 1);
  const info: OrfSearchInfo = {
    table: parseInt(dnaOrfTableSelect.value, 10) || 1,
    starts: dnaOrfStartsSelect.value === "table" ? "table" : "ATG",
  };
  currentOrfs = [];
  currentOrfInfo = null;
  dnaOrfInsert.disabled = true;
  // Tables 27, 28 and 31 have codons that are stop OR sense by context, so
  // there is no honest ORF boundary: the engine refuses them by name
  // (GeneticCodeError), and that text is what the user sees.
  try {
    currentOrfs = findOrfs(seq, { minAa, table: info.table, starts: info.starts });
  } catch (e) {
    const msg = e instanceof GeneticCodeError ? e.message : `Could not search for ORFs: ${(e as Error).message}`;
    dnaOrfResults.innerHTML = `<span class="hint">${esc(msg)}</span>`;
    setStatus(msg, "error");
    return;
  }
  if (!currentOrfs.length) {
    dnaOrfResults.innerHTML = `<span class="hint">No ORFs ≥ ${minAa} aa found in any of the six frames (${esc(geneticCodeLabel(info.table ?? 1))}).</span>`;
    return;
  }
  currentOrfInfo = info;
  dnaOrfResults.innerHTML = buildOrfTableHtml(currentOrfs, info);
  dnaOrfInsert.disabled = false;
  setStatus(`Found ${currentOrfs.length} ORF${currentOrfs.length === 1 ? "" : "s"}.`, "success");
}

/** Inserts the most recent ORF results as a Word table. */
async function insertOrfTable(): Promise<void> {
  // The settings the shown ORFs were FOUND with, not the dropdowns' current values.
  const html = currentOrfInfo ? buildOrfTableHtml(currentOrfs, currentOrfInfo) : "";
  if (!html) {
    setStatus("Run Find ORFs first.", "error");
    return;
  }
  dnaOrfInsert.disabled = true;
  setStatus("Inserting ORF table…");
  try {
    await docHost.insertAtSelection({ kind: "html", content: html, at: "replace", select: "inserted", tag: "formula-inserter:orf-table" });
    setStatus("ORF table inserted.", "success");
  } catch (error) {
    setStatus(`Could not insert the ORF table: ${(error as Error).message}`, "error");
  } finally {
    dnaOrfInsert.disabled = false;
  }
}

// ---------------------------------------------------------------------------
// Reaction schemes
// ---------------------------------------------------------------------------

/** The balanced (or refused) equation shown in Reaction mode's Formulas reading. */
let currentReactionBalance: BalanceReport | null = null;

/**
 * Reaction mode, Formulas reading (v2.137.0): balance.ts parses every species
 * as a FORMULA and balances by the null space; the equation, the conservation
 * rows and the conservation chart are shown and inserted. The Structures
 * reading below is unchanged. The two are never auto-detected between: "CO"
 * is methanol as SMILES and carbon monoxide as a formula.
 */
function updateReactionBalance(text: string): void {
  const rep = balanceReport(balanceReaction(text));
  currentReactionBalance = rep;
  reactionPreviewEl.replaceChildren();
  const head = document.createElement("div");
  head.className = rep.ok ? "ms-masses" : "hint";
  head.textContent = rep.headline;
  reactionPreviewEl.appendChild(head);
  for (const l of rep.lines) {
    const d = document.createElement("div");
    d.className = "hint";
    d.textContent = l;
    reactionPreviewEl.appendChild(d);
  }
  if (rep.svg) {
    const fig = document.createElement("div");
    fig.className = "stats-figure";
    fig.innerHTML = rep.svg;
    reactionPreviewEl.appendChild(fig);
  }
  if (rep.caveats.length) reactionPreviewEl.appendChild(specCaveats(rep.caveats));
  // A refusal is shown, not inserted: there is no equation to put in a document.
  reactionInsertBtn.disabled = !rep.ok || reactionInserting;
}

/**
 * An insert is running. A preview redrawn meanwhile (typing, a dropdown, a drawn component) must leave Insert
 * disabled until it ends, or a second click inserts the scheme twice (review).
 */
let reactionInserting = false;

/** The debounced preview after typing, if one is pending. */
let reactionPreviewTimer: ReturnType<typeof setTimeout> | null = null;

/**
 * Insert and Open in Build canvas redraw from the box at once: a preview still pending from typing must not fire
 * mid-insert and re-enable Insert (a second click would insert the scheme twice — review).
 */
function cancelReactionPreviewTimer(): void {
  if (reactionPreviewTimer) clearTimeout(reactionPreviewTimer);
  reactionPreviewTimer = null;
}

/** Renders each component and composes the live reaction-scheme preview. */
function updateReactionPreview(): void {
  currentScheme = null;
  currentReactionBalance = null;
  reactionInsertBtn.disabled = true;
  reactionOpenCanvasBtn.disabled = true;
  reactionNotesEl.replaceChildren();
  // Wrap, conditions and caption are the drawn scheme's options: hidden for the Formulas reading.
  reactionSchemeOpts.hidden = reactionReadSelect.value === "formulas";
  reactionOpenCanvasBtn.hidden = reactionReadSelect.value === "formulas";
  reactionPreviewEl.classList.remove("scheme-preview");
  const text = reactionInput.value.trim();
  const formulas = reactionReadSelect.value === "formulas";
  reactionInsertBtn.textContent = formulas ? "Insert balanced equation" : "Insert reaction scheme";
  if (!text) {
    reactionPreviewEl.replaceChildren();
    const hint = document.createElement("span");
    hint.className = "hint";
    hint.textContent = formulas
      ? "Enter a reaction of formulas, e.g. Fe + O2 -> Fe2O3 or MnO4^- + Fe^2+ + H^+ -> Mn^2+ + Fe^3+ + H2O"
      : "Enter a scheme, one item per line, e.g. aspirin (1), then -> NaOH, H2O ; 100 °C, then salicylic acid (2).";
    reactionPreviewEl.appendChild(hint);
    return;
  }
  if (formulas) {
    updateReactionBalance(text);
    return;
  }
  const reg = loadCompoundRegister();
  renderCompoundRegister(reg.register);
  const parsed = parseScheme(text);
  const typed = parsed.stages.flat().map((c) => c.label).filter((l): l is string => !!l);
  const built = buildScheme(parsed, {
    width: (reactionWidthSelect.value as SchemeWidth) || "page",
    lettered: reactionConditionsSelect.value === "lettered",
    numberFor: reactionAutonumCheck.checked ? autoNumberer(reg.register, typed) : undefined,
  });
  if (!built.ok) {
    reactionPreviewEl.replaceChildren();
    showReactionNotes(built.errors, built.notes);
    return;
  }
  // The document's numbering, checked against this scheme (warnings: the numbers are the chemist's).
  built.notes.push(...reg.notes, ...checkAgainstRegister(reg.register, built.compounds));
  // The page's own renderer drew it (its text is escaped there).
  reactionPreviewEl.innerHTML = built.svg;
  reactionPreviewEl.classList.add("scheme-preview");
  if (built.footnote) {
    const fn = document.createElement("div");
    fn.className = "scheme-footnote";
    fn.textContent = built.footnote.text;
    reactionPreviewEl.appendChild(fn);
  }
  showReactionNotes([], built.notes);
  currentScheme = built;
  reactionInsertBtn.disabled = reactionInserting;
  reactionOpenCanvasBtn.disabled = false;
}

/** The document's compound register, read from its settings (empty where the host has none). */
function loadCompoundRegister(): { register: CompoundRegister; notes: string[] } {
  try {
    return readRegister(docHost.getSetting(REGISTER_SETTING));
  } catch {
    // Not read is not empty: what is stored is never written over from here.
    return { register: { entries: [], writable: false }, notes: ["The document's compound register could not be read here, so it is not used or changed."] };
  }
}

/** Writes the register into the document's settings; resolves false (and says so) when the host could not save. */
function saveCompoundRegister(reg: CompoundRegister): Promise<boolean> {
  return new Promise((resolve) => {
    // A stored register this version could not read is never written over.
    if (reg.writable === false) return resolve(false);
    try {
      docHost.setSetting(REGISTER_SETTING, writeRegister(reg));
      docHost.saveSettings((r) => resolve(r.succeeded));
    } catch {
      resolve(false);
    }
  });
}

/** The "Compounds in this document" list: each number, its formula and what it was typed as; Insert number / Forget. */
function renderCompoundRegister(reg: CompoundRegister): void {
  reactionRegisterSummary.textContent = `Compounds in this document (${reg.entries.length})`;
  reactionRegisterList.replaceChildren();
  for (const e of reg.entries) {
    const row = document.createElement("div");
    row.className = "scheme-reg-row";
    const b = document.createElement("b");
    b.textContent = e.label;
    const what = document.createElement("span");
    what.className = "scheme-reg-what";
    what.textContent = `${typesetFormula(e.formula)}${e.text && e.text !== e.formula ? ` — ${e.text.length > 48 ? `${e.text.slice(0, 48)}…` : e.text}` : ""}`;
    const ins = document.createElement("button");
    ins.type = "button";
    ins.textContent = "Insert number";
    ins.title = `Put a bold ${e.label} at the cursor`;
    ins.addEventListener("click", () => void insertRunsText(inlineParagraphsOoxml([`<b>${esc(e.label)}</b>`]), `Compound ${e.label}`));
    const del = document.createElement("button");
    del.type = "button";
    del.textContent = "Forget";
    del.title = `Take ${e.label} out of this document's register (the document's text is not changed)`;
    del.addEventListener("click", async () => {
      const next = forgetCompound(loadCompoundRegister().register, e.label);
      const ok = await saveCompoundRegister(next);
      renderCompoundRegister(ok ? next : loadCompoundRegister().register);
      updateReactionPreview();
      setStatus(
        ok
          ? `Compound ${e.label} is no longer in this document's register; the text is unchanged — a bold ${e.label} already in the document still reads as it did, and Number new compounds may use ${e.label} again.`
          : `Compound ${e.label} could not be taken out: Word did not save the change.`,
        ok ? "success" : "error",
      );
    });
    row.append(b, what, ins, del);
    reactionRegisterList.appendChild(row);
  }
  compoundTablePane?.update();
}

/** The scheme's errors (it is not drawn) and notes (it is), beside the preview. */
function showReactionNotes(errors: string[], notes: string[]): void {
  reactionNotesEl.replaceChildren();
  for (const [list, cls] of [[errors, "scheme-error"], [notes, "scheme-warn"]] as const) {
    for (const t of list) {
      const li = document.createElement("li");
      li.className = cls;
      li.textContent = t;
      reactionNotesEl.appendChild(li);
    }
  }
}

/** The title as html, its compound numbers bold where they are this scheme's numbers ("Synthesis of 5"). */
function schemeTitleHtml(title: string, labels: string[]): string {
  return titleWithBoldLabels(title, labels, esc);
}

/**
 * Formulas reading: the balanced equation and its conservation rows go in as
 * text (a Word paragraph per line — never OMML, which would re-read Fe₂O₃),
 * then the conservation chart as a picture, ONLY if the text landed.
 */
async function insertReactionBalance(): Promise<void> {
  const rep = currentReactionBalance;
  if (!rep || !rep.ok) {
    setStatus("Nothing to insert — the reaction is not balanced.", "error");
    return;
  }
  const blocks: DerivationBlock[] = [rep.headline, ...rep.lines, ...rep.caveats].map((t) => ({ kind: "text" as const, content: t }));
  const plain = [rep.headline, ...rep.lines, ...rep.caveats].join("\n");
  reactionInsertBtn.disabled = true;
  try {
    if (!rep.svg) {
      await insertDerivation(blocks, plain, "Balanced equation");
      return;
    }
    // One package, text then chart (v2.193.0): two batches could put the chart above the equation.
    await insertDerivationWithFigure(blocks, plain, "Balanced equation", {
      svg: rep.svg,
      fallbackW: 380,
      fallbackH: 260,
      alt: rep.alt,
      done: "Balanced equation and conservation chart inserted.",
    });
  } finally {
    reactionInsertBtn.disabled = false;
  }
}

/** Rasterizes the reaction scheme and inserts it as an inline picture. */
async function insertReaction(): Promise<void> {
  cancelReactionPreviewTimer();
  if (reactionInserting) return;
  reactionInserting = true;
  try {
    await insertReactionNow();
  } finally {
    reactionInserting = false;
    reactionInsertBtn.disabled = reactionReadSelect.value === "formulas" ? !currentReactionBalance?.ok : !currentScheme;
  }
}

async function insertReactionNow(): Promise<void> {
  if (reactionReadSelect.value === "formulas") {
    await insertReactionBalance();
    return;
  }
  updateReactionPreview();
  const sc = currentScheme;
  if (!sc) {
    setStatus("Nothing to insert — the scheme is not drawn (see the notes under it).", "error");
    return;
  }
  // The smallest text drawn (a subscript in H₂SO₄ is 7.5 pt), read off the drawing itself for the USPTO check.
  const smallest = smallestFontPt(sc.svg) ?? 10;
  const fit = canvasInsertFit(canvasInsertMode(), sc.widthPt, sc.heightPt, smallest, USPTO_REQUIRED_FONT_PT);
  if (!fit.ok) return setStatus(`The scheme: ${fit.reason}.`, "error");
  const w = (fit.widthPt * 96) / 72, h = (fit.heightPt * 96) / 72;
  reactionInsertBtn.disabled = true;
  setStatus("Inserting reaction scheme…");
  try {
    // ONE PACKAGE: caption, picture and footnote (v2.193.0). They were three inserts chained through
    // insertResultLayout, each anchored on the range the one before returned; Word gives no usable insertion point
    // after an inserted OOXML package, so the picture and the footnote could silently not land. The caption keeps its
    // SEQ Scheme field and its Caption pStyle. The package has NO styles part (one rewrote the document's own Caption
    // style), and without it Word leaves the paragraph Normal (measured via COM), so the host sets the built-in Caption
    // style on that first paragraph afterwards (captionPrefix), applying the document's own definition.
    const items: ResultPackageItem[] = [];
    let n = 0;
    if (reactionCaptionCheck.checked) {
      // The number Word shows until it updates the field: the Scheme captions already here, plus one.
      let paras: string[] = [];
      try {
        paras = await docHost.readParagraphTexts();
      } catch {
        paras = [];
      }
      n = countSchemeCaptions(paras) + 1;
      const labels = sc.compounds.map((c) => c.label).filter((l): l is string => !!l);
      items.push({ kind: "xml", content: packageBodyXml(schemeCaptionOoxml(n, schemeTitleHtml(reactionTitleInput.value, labels))) });
    }
    const base64 = await renderFigurePng(sc.svg, w, h);
    const numbered = sc.compounds.filter((c) => c.label).map((c) => `${c.label} = ${c.smiles}`);
    const alt = `Reaction scheme (JurisLab): ${reactionInput.value.trim().replace(/\s*\n\s*/g, "\n")}` + (numbered.length ? `. Compounds: ${numbered.join("; ")}` : "");
    items.push({ kind: "picture", caption: "", base64, widthPt: figurePoints(w), heightPt: figurePoints(h), alt });
    if (sc.footnote) items.push({ kind: "xml", content: packageBodyXml(inlineParagraphsOoxml([sc.footnote.html])) });
    const kept = await docHost.insertResultLayout([{ kind: "ooxml", ooxml: buildResultOoxml(items).ooxml, captionPrefix: n > 0 ? "Scheme " : undefined }]);
    if (kept === 0) return setStatus("Word did not keep the scheme picture — try again with the cursor in a body paragraph.", "error");
    const parts = [n ? `Scheme ${n}` : "Reaction scheme", sc.footnote ? "with its Reagents and conditions footnote" : ""].filter(Boolean).join(" ");
    // The numbers go into the document's register only once the scheme is in the document.
    const merged = mergeIntoRegister(loadCompoundRegister().register, sc.compounds);
    let regNote = "";
    let regFailed = false;
    if (merged.added.length || merged.kept.length) {
      const saved = merged.added.length ? await saveCompoundRegister(merged.register) : true;
      regFailed = !saved;
      if (saved) renderCompoundRegister(merged.register);
      if (merged.added.length)
        regNote += saved
          ? ` Compound${merged.added.length === 1 ? "" : "s"} ${merged.added.join(", ")} added to this document's register.`
          : merged.register.writable === false
            ? " The numbers were not registered: this document's compound register could not be read, and it is left as it is."
            : " Word could not save the compound register.";
      if (merged.kept.length)
        regNote += ` ${merged.kept.join(", ")} ${merged.kept.length === 1 ? "stays" : "stay"} registered for the structure already there; this scheme's ${merged.kept.length === 1 ? "use is" : "uses are"} not recorded.`;
    }
    setStatus(`${parts} inserted.${regNote} ${fit.note}${n ? " Word renumbers Scheme captions when fields update (select all, F9)." : ""}`.trim(), regFailed ? "error" : merged.kept.length ? "" : "success");
  } catch (error) {
    setStatus(`Could not insert reaction scheme: ${(error as Error).message}`, "error");
  } finally {
    reactionInsertBtn.disabled = false;
  }
}

/** The scheme's page on the Build canvas, to move or edit anything by hand; Insert there puts it in as drawn. */
function openSchemeInCanvas(): void {
  cancelReactionPreviewTimer();
  updateReactionPreview();
  const sc = currentScheme;
  if (!sc) return setStatus("Nothing to open — the scheme is not drawn.", "error");
  setMode("build");
  setBuildTab("draw");
  ensureDrawEditor();
  const pc = usePageCanvas();
  if (!pc) return setStatus("The Build page canvas could not open.", "error");
  pc.loadPage(sc.doc);
  pc.setName("Scheme");
  drawFromPicture = false;
  setStatus("The scheme opened on the Build page canvas — move or edit anything, then Insert there.", "success");
  document.getElementById("build-draw-wrap")?.scrollIntoView({ block: "start" });
}

// ---------------------------------------------------------------------------
// Document audit + SEQ ID references
// ---------------------------------------------------------------------------

/** Reads the document and runs the full consistency audit. */
async function runAudit(): Promise<void> {
  auditRunBtn.disabled = true;
  setStatus("Checking the application…");
  try {
    const bodyText = await docHost.readBodyText();
    const report = auditDocument({
      documentText: bodyText,
      numerals: numeralEntries,
      listingCount: readSequenceEntries().length,
    });
    renderAuditReport(report);
    setStatus("Audit complete.", "success");
  } catch (error) {
    setStatus(`Could not run the audit: ${(error as Error).message}`, "error");
  } finally {
    auditRunBtn.disabled = false;
  }
}

/** Renders the audit report grouped by section. */
function renderAuditReport(report: AuditReport): void {
  // THREE states, not two. A section with no issues used to render a green "✓"
  // whether it had passed or could not be checked at all, which is a false
  // all-clear. `notes` carries the "not checked, and here is why" case — the
  // sequence section hit it on every fresh Word session, where the listing lives
  // only in the pane's DOM and is empty until something is loaded.
  const noteList = (s: { notes?: string[] }): string =>
    s.notes?.length ? `<ul>${s.notes.map((n) => `<li>${esc(n)}</li>`).join("")}</ul>` : "";
  const blocks = report.sections.map((s) => {
    if (!s.issues.length) {
      const cls = s.notes?.length ? "audit-block" : "audit-block ok";
      const mark = s.notes?.length ? "•" : "✓";
      return `<div class="${cls}"><strong>${mark} ${esc(s.title)}</strong>${noteList(s)}</div>`;
    }
    return (
      `<div class="audit-block error"><strong>${esc(s.title)} — ${s.issues.length} issue${
        s.issues.length === 1 ? "" : "s"
      }</strong><ul>${s.issues.map((i) => `<li>${esc(i)}</li>`).join("")}</ul>${noteList(s)}</div>`
    );
  });
  const header = report.ok
    ? '<div class="audit-summary ok">✓ No issues found.</div>'
    : `<div class="audit-summary error">${report.issueCount} issue${report.issueCount === 1 ? "" : "s"} across ${report.sections.filter((s) => s.issues.length).length} area(s).</div>`;
  auditResults.innerHTML = header + blocks.join("");
}

/** Inserts a canonical "SEQ ID NO: N" reference at the selection. */
async function insertSeqIdRef(): Promise<void> {
  // ACCEPTS A LIST OR A RANGE, not just one number. `formatSeqIdRefs` was
  // written to collapse 1,2,3,7 into "SEQ ID NOs: 1-3 and 7" and had no caller,
  // so a specification citing a run of sequences — the normal case in a biotech
  // application — got them one insertion at a time.
  const raw = seqRefNum.value.trim();
  const nums: number[] = [];
  for (const part of raw.split(/[,;\s]+/).filter(Boolean)) {
    const range = /^(\d+)\s*[-–]\s*(\d+)$/.exec(part);
    if (range) {
      const lo = parseInt(range[1], 10);
      const hi = parseInt(range[2], 10);
      if (lo < 1 || hi < lo || hi - lo > 999) {
        setStatus(`"${part}" is not a usable range of SEQ ID numbers.`, "error");
        return;
      }
      for (let i = lo; i <= hi; i++) nums.push(i);
      continue;
    }
    const n = parseInt(part, 10);
    if (!Number.isFinite(n) || n < 1 || String(n) !== part) {
      setStatus(`"${part}" is not a SEQ ID number.`, "error");
      return;
    }
    nums.push(n);
  }
  if (!nums.length) {
    setStatus("Enter a SEQ ID number ≥ 1, a list (1, 2, 5) or a range (1-3).", "error");
    return;
  }
  const text = nums.length === 1 ? formatSeqIdRef(nums[0]) : formatSeqIdRefs(nums);
  await insertPlainText(text, "SEQ ID reference");
}

