      const res = capacityFactor(mw, mwh, hours ?? undefined);
      if (!res.ok) return { text: res.error, ok: false };
      // One precision for the whole table: a 4-figure CF sat beside "18000 MWh" and "3100 h" rounded to the inputs' figures.
