/** Scans the document for citations and inserts a grouped Table of Authorities. */
async function buildToaHandler(): Promise<void> {
  toaBuildBtn.disabled = true;
  toaMsg.className = "build-readout";
  setStatus("Scanning document for citations…");
  try {
    const rep = await docHost.buildStaticToa();
    if (!("groups" in rep)) {
      toaMsg.textContent = "No citations found to build a Table of Authorities.";
      setStatus("No citations found.", "");
      return;
    }
    const summary = rep.groups.map((g) => `${g.count} ${g.heading.toLowerCase()}`).join(", ");
    let pageNote: string;
    if (rep.pagesFilled) pageNote = `Page numbers filled in (${rep.pagesFilled}).` + (rep.replacedField ? " The field table was replaced." : "");
    else
      pageNote =
        "Page slots are blank — Word can only compute pages through a field. To fill them: click " +
        "“Insert with live page numbers”, select all (Ctrl/⌘+A) and press F9, then click “Insert formatted list”.";
    toaMsg.textContent = `Inserted ${rep.total} authorit${rep.total === 1 ? "y" : "ies"} (${summary}), Times New Roman, italic names. ${pageNote}`;
    setStatus("Formatted Table of Authorities inserted.", rep.pagesFilled ? "success" : "");
  } catch (error) {
    setStatus(`Could not build the Table of Authorities: ${(error as Error).message}`, "error");
  } finally {
    toaBuildBtn.disabled = false;
  }
}

/** Copies the plain-text citation to the clipboard. */
async function copyCitation(): Promise<void> {
  if (!currentCitation) return;
  try {
    await navigator.clipboard.writeText(currentCitation.plain);
    setStatus("Citation copied to clipboard.", "success");
  } catch {
    setStatus("Clipboard unavailable — select the preview text to copy.", "");
  }
}

// ---------------------------------------------------------------------------
// Citations ▸ Bibliography (v2.142.0). Every decision is in lib/bibPane.ts (tested in
// bibPaneRouting.test.ts); this block only reads and writes Word.
//   - library + style: document settings key BIB_SETTING_KEY (bibStore.ts);
//   - each citation: a content control tagged formula-inserter:cite:<id>;
//   - the bibliography: one content control tagged BIBLIOGRAPHY_TAG.
// Insert and Update each run in ONE Word.run, so one Ctrl+Z reverts the whole pass.
// ---------------------------------------------------------------------------

/** Why the document's library cannot be edited (newer version, damaged), or null. */
let bibStoreRefusal: string | null = null;
/** The style changed since the last update: rewrite every marker, not only changed text. */
let bibStyleDirty = false;

function readBibStore(): BibStoreData | null {
  let raw: unknown = null;
  try {
    raw = docHost.getSetting(BIB_SETTING_KEY);
  } catch {
    raw = null;
  }
  const r = loadBibStore(raw, ((bibStyleSelect && bibStyleSelect.value) || "ieee") as StyleId);
  if (!r.ok) {
    bibStoreRefusal = r.reason;
    return null;
  }
  bibStoreRefusal = null;
  return r.store;
}

/** Saves the store in the document; resolves to a reason when it could not. */
function writeBibStore(store: BibStoreData): Promise<string | null> {
  const s = serializeStore(store);
  if (!s.ok) return Promise.resolve(s.reason);
  return new Promise((resolve) => {
    try {
      docHost.setSetting(BIB_SETTING_KEY, s.json);
      docHost.saveSettings((res) => {
        resolve(
          res.succeeded
            ? null
            : `The reference library could not be saved in the document: ${res.error ? res.error.message : "unknown error"}.`
        );
      });
    } catch (e) {
      resolve(`The reference library could not be saved in the document: ${(e as Error).message}`);
    }
  });
}

/** Renders formatted html (escaped text + <i>/<b>/<sup>/<sub>) as DOM nodes, never as innerHTML. */
function appendRuns(parent: HTMLElement, runs: MarkerRun[]): void {
  for (const r of runs) {
    let node: Node = document.createTextNode(r.text);
    for (const [on, tag] of [
      [r.sup, "sup"],
      [r.sub, "sub"],
      [r.italic, "i"],
      [r.bold, "b"],
    ] as Array<[boolean, string]>) {
      if (!on) continue;
      const el = document.createElement(tag);
      el.appendChild(node);
      node = el;
    }
    parent.appendChild(node);
  }
}

/** Fills the style list, notes and library list from the document's store. */
function refreshBibPanel(): void {
  if (!bibStyleSelect) return;
  bibDoiNote.textContent = DOI_OFFLINE_NOTE;
  bibCaseNote.textContent = CASE_NOTE;
  if (!bibStyleSelect.options.length) {
    for (const s of offeredStyles()) bibStyleSelect.add(new Option(s.name, s.id));
    bibStyleNote.textContent = notOfferedNote();
  }
  const store = readBibStore();
  const blocked = !store;
  for (const b of [bibImportBtn, bibOpenBtn, bibInsertBtn, bibUpdateBtn]) b.disabled = blocked;
  bibStyleSelect.disabled = blocked;
  if (!store) {
    bibMsg.textContent = bibStoreRefusal ?? "";
    return;
  }
  if (Array.from(bibStyleSelect.options).some((o) => o.value === store.style)) bibStyleSelect.value = store.style;
  const selected = new Set(Array.from(bibLibrarySelect.selectedOptions).map((o) => o.value));
  bibLibrarySelect.textContent = "";
  for (const row of libraryRows(store)) {
    const opt = new Option(row.label, row.id);
    opt.selected = selected.has(row.id);
    bibLibrarySelect.add(opt);
  }
  renderBibPreview();
}

/** How the selected references print in the chosen style; refusals and recased titles by name. */
function renderBibPreview(): void {
  bibPreview.textContent = "";
  const store = readBibStore();
  if (!store) return;
  const ids = Array.from(bibLibrarySelect.selectedOptions).map((o) => o.value);
  if (!ids.length) {
    bibPreview.textContent = Object.keys(store.library).length
      ? "Select references in the library list to see them in this style."
      : "The library is empty: import BibTeX, RIS or CSL-JSON above.";
    return;
  }
  const recs = ids.map((id) => store.library[id]).filter(Boolean);
  for (const p of previewRecords(store.style, recs)) {
    const row = document.createElement("div");
    row.className = "examples-note";
    const key = document.createElement("strong");
    key.textContent = `${p.id}: `;
    row.appendChild(key);
    if (p.formatted) appendRuns(row, markerRuns(p.formatted.html));
    else row.appendChild(document.createTextNode(`refused: ${p.refusal ?? ""}`));
    if (p.recased) row.appendChild(document.createTextNode(` [title case changed; as imported: “${p.original}”]`));
    for (const w of p.warnings) row.appendChild(document.createTextNode(` [${w}]`));
    bibPreview.appendChild(row);
  }
}

async function importBibliographyFile(): Promise<void> {
  const file = bibFileInput.files && bibFileInput.files[0];
  bibFileInput.value = ""; // so re-choosing the same file fires again
  if (!file) return;
  if (file.size > 8 * 1024 * 1024) {
    bibImportMsg.textContent = `${file.name}: over 8 MB, too large to load into the pane.`;
    return;
  }
  let text: string;
  try {
    text = await file.text();
  } catch {
    bibImportMsg.textContent = `${file.name}: could not be read.`;
    return;
  }
  await importBibliographyText(text, file.name);
}

/** Import a paste or a file into the document's library. Nothing is fetched. */
async function importBibliographyText(text: string, fileName?: string): Promise<void> {
  const store = readBibStore();
  if (!store) {
    bibImportMsg.textContent = bibStoreRefusal ?? "";
    return;
  }
  if (!text.trim()) {
    bibImportMsg.textContent = "Paste BibTeX, RIS, CSL-JSON or a DOI first, or open a file.";
    return;
  }
  const rep = importBibText(text, fileName);
  const lines = [(fileName ? `${fileName}: ` : "") + importSummary(rep), ...rep.lines];
  if (rep.note) lines.push(rep.note);
  if (rep.format === "doi") lines.push(...doiLibraryLines(rep.dois, store));
  if (rep.records.length) {
    const m = mergeImport(store, rep.records);
    if (m.result.added.length || m.result.renamed.length) {
      const err = await writeBibStore(m.store);
      if (err) lines.push(`Nothing was added to the library: ${err}`);
      else lines.push(...m.lines);
    } else lines.push(...m.lines);
  }
  bibImportMsg.textContent = lines.join("\n");
  refreshBibPanel();
}

async function changeBibStyle(): Promise<void> {
  const store = readBibStore();
  if (!store) return;
  const id = bibStyleSelect.value as StyleId;
  if (id === store.style) return;
  const err = await writeBibStore({ ...store, style: id });
  if (err) {
    bibMsg.textContent = err;
    bibStyleSelect.value = store.style;
    return;
  }
  bibStyleDirty = true;
  bibMsg.textContent = `Style: ${bibStyleSelect.selectedOptions[0]?.text ?? id}. Press “Update numbering & bibliography” to restyle the citations already in the document.`;
  renderBibPreview();
}

/**
 * The renumbering report, worded for the pane. The renumbering itself runs in
 * the host (src/host/wordDocument.ts applyBibUpdate), inside the caller's batch.
 */
function bibUpdateLines(r: BibUpdateReport): string[] {
  if (!r.ok) return [r.reason];
  const lines: string[] = [];
  const b = r.bibliography;
  if (b && b.kind === "replaced") {
    lines.push(`Bibliography replaced: ${b.references} reference${b.references === 1 ? "" : "s"}.`);
    if (b.blocks > 1) lines.push(`${b.blocks} bibliography blocks are in the document; only the first was updated. Delete the others.`);
  } else if (b && b.kind === "inserted") {
    lines.push(
      `Bibliography inserted at the end of the document: ${b.references} reference${b.references === 1 ? "" : "s"}. ` +
        "Cut and paste it anywhere; Update finds it by its tag."
    );
  }
  lines.unshift(`Updated ${r.rewrites} citation${r.rewrites === 1 ? "" : "s"} (${r.occurrences} in the document).`);
  return [...lines, ...r.report];
}

/** Insert citation: a new tagged marker at the cursor, or added to the citation the cursor is in. */
async function insertBibCitation(): Promise<void> {
  const store = readBibStore();
  if (!store) {
    bibMsg.textContent = bibStoreRefusal ?? "";
    return;
  }
  const ids = Array.from(bibLibrarySelect.selectedOptions).map((o) => o.value);
  const style = getStyle(store.style);
  const isNote = !!style && style.kind === "note";
  if (isNote && !wordApiSupported("1.5")) {
    bibMsg.textContent = `${style ? style.name : store.style} puts citations in footnotes, and this version of Word cannot insert content into a footnote (WordApi 1.5). Choose a numeric or author-date style.`;
    return;
  }
  let saved: BibStoreData | null = null;
  let lines: string[] = [];
  try {
    // The plan is made INSIDE the host's batch, from the tag of the citation the
    // cursor is in; every refusal (an unsaveable store, a tag over Word's limit)
    // is decided BEFORE anything touches the document.
    const res = await docHost.insertBibCitation({
      isNote,
      plan: (existingTag) => {
        const plan = planInsert(store, ids, {
          locator: bibLocatorInput.value,
          label: bibLocLabelSelect.value,
          existingTag,
        });
        if (!plan.ok) return { ok: false, lines: plan.reasons };
        // Check that the new store can be saved BEFORE touching the document.
        const ser = serializeStore(plan.store);
        if (!ser.ok) return { ok: false, lines: [ser.reason] };
        if (plan.kind !== "new") return { ok: true, kind: "add", store: plan.store };
        const t = citeTag(plan.markerId); // refuses a tag over Word's limit, by name
        if (!t.ok) return { ok: false, lines: [t.reason] };
        return { ok: true, kind: "new", tag: t.tag, title: CITE_CONTROL_TITLE, store: plan.store };
      },
      // Read when the renumbering starts, inside the batch, as before (the style
      // may change while an insert is in flight).
      update: () => ({ rewriteAll: bibStyleDirty, bibliography: "if-present" }),
    });
    if ("refused" in res) lines = res.refused;
    else {
      lines = [res.kind === "new" ? "Citation inserted." : "Added to the citation at the cursor.", ...bibUpdateLines(res.update)];
      saved = res.store;
    }
  } catch (e) {
    lines = [`Could not insert the citation: ${(e as Error).message}`];
  }
  if (saved) {
    const err = await writeBibStore(saved);
    if (err) lines.push(`${err} The citation is in the document but its references were not saved; press Ctrl/⌘+Z.`);
    else bibStyleDirty = false;
  }
  bibMsg.textContent = lines.join("\n");
}

/** Update numbering & bibliography: one pass over every citation, then the bibliography block. */
async function updateBibliography(forceAll: boolean): Promise<void> {
  const store = readBibStore();
  if (!store) {
    bibMsg.textContent = bibStoreRefusal ?? "";
    return;
  }
  let lines: string[] = [];
  try {
    const res = await docHost.updateBibliography(store, { rewriteAll: forceAll || bibStyleDirty, bibliography: "always" });
    lines = bibUpdateLines(res);
    if (res.ok) bibStyleDirty = false;
  } catch (e) {
    lines = [`Could not update the citations: ${(e as Error).message}`];
  }
  bibMsg.textContent = lines.join("\n");
}

/** Reads an SVG's intrinsic width/height (px), falling back to the given box. */
/** Rasterises at the supersampled size. Pair with figurePoints() sizing at the insert (lib/figures.ts). */
async function renderFigurePng(svg: string, width: number, height: number): Promise<string> {
  // A PIXEL BUDGET IS NOT A BYTE BUDGET.
  //
  // figureScale bounds how much memory the canvas costs. What Word cares about
  // is the size of the base64 payload handed to insertInlinePictureFromBase64,
  // and a picture over that limit is not rejected — it is accepted, reported as
  // fine, and silently dropped. Two Bode plots at 4x did exactly that.
  //
  // So the payload is measured, not assumed, and the figure is re-rendered at a
  // lower supersampling factor until it fits. Resolution degrades; the figure
  // still arrives. The worst case is 1x, which is the natural size and always
  // small enough.
  const MAX_BASE64 = 1_400_000;
  let s = figureScale(width, height);
  let png = await svgToPngBase64(svg, Math.round(width * s), Math.round(height * s));
  while (png.length > MAX_BASE64 && s > 1) {
    s--;
    png = await svgToPngBase64(svg, Math.round(width * s), Math.round(height * s));
  }
  return png;
}

// ---------------------------------------------------------------------------
// One figure insert path: figure style, vector or PNG, re-find and size (v2.143.0)
// ---------------------------------------------------------------------------

/** What this host can do, read once per insert. Unknown is never "yes" (unlike wordApiSupported). */
function hostCapability(): HostCapability {
  return { ...docHost.capability(), vectorRequested: !!figVectorCheckbox?.checked };
}

/** The figure style chosen in the pane ("As drawn" unless the user picked one). */
function currentFigurePreset(): FigurePresetChoice {
  const v = figStyleSelect?.value as FigurePresetChoice | undefined;
  return v && (FIGURE_PRESET_CHOICES as readonly string[]).includes(v) ? v : "asdrawn";
}

function currentFigureWidth(): PresetWidth {
  const v = figWidthSelect?.value;
  return v === "oneAndHalf" || v === "double" ? v : "single";
}

function updateFigureStyleNote(): void {
  const choice = currentFigurePreset();
  figWidthSelect.disabled = choice === "asdrawn";
  figStyleNote.textContent = figureStyleNote(choice, currentFigureWidth());
  // Table→Chart draws with the style's palette (Okabe–Ito under a journal style,
  // black-and-white hatching under USPTO), so its preview follows the choice: the
  // preview is the figure that will be inserted, not a different one.
  if (currentMode() === "ppt") updatePptPreview();
}

/** The Stats bracket controls, read as one choice. */
function currentBracketChoice(): BracketChoice {
  const v = statsBracketsSelect?.value;
  return {
    label: v === "stars" || v === "p" ? v : "off",
    hideNs: !!statsBracketsHideNs?.checked,
    tall: !!statsBracketsTall?.checked,
  };
}

/**
 * Modes whose figure inserts go through insertFigure, so the figure-style row is
 * shown there and ONLY there (onInputChanged). Every other figure tool —
 * Engineering, Spectra, Sequence Map, Solve, the substituent gallery, the 3D
 * model — still inserts PNG as drawn through its own path; TEST-SCRIPT §0cj
 * checks that the row is absent from them. A mode is added here in the same
 * change that routes its insert through insertFigure (figurePaneRouting.test.ts
 * pins the pairing).
 */
const FIGURE_STYLE_MODES = new Set<string>(["plot", "ppt", "stats", "finance", "assay", "solidform"]);

interface FigureInsert {
  svg: string;
  fallbackW: number;
  fallbackH: number;
  alt: string;
  /** tagInserted tag, if the site tags its picture. */
  tag?: string;
  /** Re-render the same figure on a canvas `w` units wide (lets a preset fit it). */
  render?: (w: number, style?: FigureStylePreset) => string;
  chartKind?: string;
  /**
   * The site's own supersampling before figureScale (Stats and Finance rendered
   * at 2× their natural size). Kept so an "As drawn" insert is the same PNG as
   * before figure styles existed.
   */
  supersample?: number;
  /** What follows the picture in the same batch: a caption line, or Table → Chart's data table. */
  tail?: FigureTail;
  /**
   * A results table between the text and the picture, in the same package (insertTextWithFigure only; the Finance
   * damages calculators). A result with a table always goes in as one package: the vector route's chained second
   * insert has no usable anchor after a table.
   */
  table?: { label: string; rows: string[][] };
}

/** A caption line under the figure, with the cursor after it — or no tail when there is no caption. */
function captionTail(caption: string): FigureTail | undefined {
  return caption ? { kind: "caption", text: caption } : undefined;
}

/**
 * Inserts one figure after the selection, under the pane's figure style, as PNG
 * (or as vector SVG when the user asked for it and Word supports it). Returns the
 * words for the status line ("as PNG at 384 dpi (Nature, 89 mm, text 5.0–7.0 pt)").
 * Throws with every violation named when the style refuses the figure.
 *
 * "As drawn" with vector off is the pre-v2.143 insert, byte for byte: the same
 * SVG, rendered at the same px (times the site's own supersampling), pinned to
 * the same points, with the same alt text and tag.
 */
async function insertFigure(o: FigureInsert): Promise<string> {
  const prepared = prepareFigure(
    { svg: o.svg, preset: currentFigurePreset(), width: currentFigureWidth(), render: o.render, chartKind: o.chartKind },
    o.fallbackW,
    o.fallbackH,
  );
  if (!prepared.ok) throw new Error(refusalText(prepared));
  const route = decideInsertRoute(hostCapability());
  const style = prepared.presetNote ? ` (${prepared.presetNote})` : "";
  let rasterWhy = route.reason;
  if (route.route === "svg") {
    const v = await docHost.insertFigureVector({
      svg: prepared.svg,
      widthPt: prepared.widthPt,
      heightPt: prepared.heightPt,
      alt: o.alt,
      tag: o.tag,
      tail: o.tail,
    });
    if (v.fallback === null) {
      const stored = v.format && v.format.toLowerCase() !== "svg" ? ` — but Word reports it stored the picture as ${v.format}` : "";
      return `as ${insertedDescription("svg", null)}${style}${stored}`;
    }
    rasterWhy = v.fallback;
  }
  const t = rasterTarget(prepared, o.supersample ?? 1);
  const png = await renderFigurePng(prepared.svg, t.w, t.h);
  const kept = await docHost.insertFigurePng({
    base64: png,
    widthPt: prepared.widthPt,
    heightPt: prepared.heightPt,
    alt: o.alt,
    tag: o.tag,
    tail: o.tail,
  });
  // WORD'S OWN COUNT, NOT OURS (v2.193.0). renderFigurePng steps the scale down while the PNG is over its payload
  // size, but at 1× it sends what it has; Word can accept a large picture and keep nothing, with no error.
  if (kept === 0) throw new Error(pictureNotKeptText(png.length));
  // The dpi of the PNG that was inserted, read from its own header (pngPixelSize),
  // not the factor that was asked for: the payload loop may have stepped it down.
  const px = pngPixelSize(png);
  const dpi = px ? rasterDpi(px.width, prepared.widthPt) : null;
  return `as ${insertedDescription("png", dpi)}${style}${rasterWhy ? `; not vector: ${rasterWhy}` : ""}`;
}

/**
 * A result's text and its results TABLE as one package (no figure): the damages calculators when their figure is
 * absent or could not be made. Same contract as insertPlainText: refused while another insert runs, and success is
 * claimed only when Word took the package.
 */
async function insertTextAndTable(text: string, table: { label: string; rows: string[][] }, label: string): Promise<boolean> {
  if (!text.trim()) {
    setStatus(`Nothing to insert for ${label.toLowerCase()}.`, "error");
    return false;
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  try {
    const built = buildResultOoxml([
      { kind: "text", content: text.replace(/\s+$/, "") },
      { kind: "table", label: table.label, rows: table.rows },
    ]);
    await docHost.insertResultLayout([{ kind: "ooxml", ooxml: built.ooxml }]);
    setStatus(`${label} and table inserted. Ctrl/⌘+Z undoes it.`, "success");
    return true;
  } catch (error) {
    setStatus(`Could not insert ${label.toLowerCase()}: ${(error as Error).message}`, "error");
    return false;
  } finally {
    insertTextBusy = false;
  }
}

/**
 * A result's TEXT AND ITS FIGURE as ONE package (fix2-plat): the text lines as paragraphs, the picture in its own
 * paragraph below them, then the figure's caption line — the Engineering path. Two inserts (text, then picture after
 * the caret) put the chart on the last text line in Word (measured via COM). The figure goes through the pane's
 * figure style exactly as insertFigure takes it (prepareFigure, rasterTarget); the vector route, which a package
 * cannot carry, keeps the two-step insert with the text ending on a paragraph break.
 *
 * Contract kept from the three callers (Statistics, Finance, Bio/Assay): nothing is claimed that did not land; a
 * second click while one insert runs is refused; when the text lands without the figure the status says the text
 * is in, so a retry does not duplicate it. Resolves true when the text landed.
 */
async function insertTextWithFigure(text: string, label: string, o: FigureInsert, done: string): Promise<boolean> {
  if (!text.trim()) {
    setStatus(`Nothing to insert for ${label.toLowerCase()}.`, "error");
    return false;
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  const textOnly = async (why: string): Promise<boolean> => {
    const ok = o.table ? await insertTextAndTable(text, o.table, label) : await insertPlainText(text, label);
    if (ok) setStatus(`${label} inserted, but the figure could not be: ${why}`, "error");
    return ok;
  };
  const prepared = prepareFigure(
    { svg: o.svg, preset: currentFigurePreset(), width: currentFigureWidth(), render: o.render, chartKind: o.chartKind },
    o.fallbackW,
    o.fallbackH,
  );
  if (!prepared.ok) return textOnly(refusalText(prepared));
  if (!o.table && decideInsertRoute(hostCapability()).route === "svg") {
    // Vector: the text first, ending on its own paragraph, then the picture on the paragraph after it.
    if (!(await insertPlainText(`${text.replace(/\s+$/, "")}\n`, label, true))) return false;
    try {
      const how = await insertFigure(o);
      setStatus(`${done} (figure ${how}).`, "success");
    } catch (error) {
      setStatus(`${label} inserted, but the figure could not be: ${(error as Error).message}`, "error");
    }
    return true;
  }
  let png: string;
  try {
    const t = rasterTarget(prepared, o.supersample ?? 1);
    png = await renderFigurePng(prepared.svg, t.w, t.h);
  } catch (error) {
    return textOnly((error as Error).message);
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  let why = "";
  try {
    const items: ResultPackageItem[] = [
      { kind: "text", content: text.replace(/\s+$/, "") },
      ...(o.table ? [{ kind: "table" as const, label: o.table.label, rows: o.table.rows }] : []),
      {
        kind: "picture",
        caption: "",
        base64: png,
        widthPt: prepared.widthPt,
        heightPt: prepared.heightPt,
        alt: o.alt,
        below: o.tail?.kind === "caption" && o.tail.text ? o.tail.text : undefined,
      },
    ];
    const built = buildResultOoxml(items);
    const kept = await docHost.insertResultLayout([{ kind: "ooxml", ooxml: built.ooxml }]);
    if (kept !== null && kept < built.pictures) {
      setStatus(`${label} inserted, but ${pictureNotKeptText(png.length)}`, "error");
      return true;
    }
    const px = pngPixelSize(png);
    const dpi = px ? rasterDpi(px.width, prepared.widthPt) : null;
    const style = prepared.presetNote ? ` (${prepared.presetNote})` : "";
    setStatus(`${done} (figure as ${insertedDescription("png", dpi)}${style}). Ctrl/⌘+Z undoes it.`, "success");
    return true;
  } catch (error) {
    why = (error as Error).message;
  } finally {
    insertTextBusy = false;
  }
  // The package was refused: the text alone, and say the figure is missing.
  return textOnly(why);
}

/**
 * A result's text, its Word TABLES and (optionally) its figure as ONE package (E1b: litigation damages). Always the
 * package route: a table cannot ride the vector route's chained insert (Word gives no usable insertion point after a
 * table, lib/resultOoxml.ts). The figure goes through the pane's figure style (prepareFigure, rasterTarget) as in
 * insertTextWithFigure. If the figure cannot be drawn, the text and tables go in without it and the status says so;
 * if Word refuses the package, the text and the tables as tab-separated lines go in as plain text.
 */
async function insertTextTablesFigure(
  text: string,
  tables: { label: string; rows: string[][]; note?: string; align?: ("left" | "center" | "right")[] }[],
  o: FigureInsert | null,
  label: string,
): Promise<boolean> {
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  let picture: ResultPackageItem | null = null;
  let figureWhy = "";
  let png = "";
  if (o) {
    const prepared = prepareFigure(
      { svg: o.svg, preset: currentFigurePreset(), width: currentFigureWidth(), render: o.render, chartKind: o.chartKind },
      o.fallbackW,
      o.fallbackH,
    );
    if (!prepared.ok) figureWhy = refusalText(prepared);
    else {
      try {
        const t = rasterTarget(prepared, o.supersample ?? 1);
        png = await renderFigurePng(prepared.svg, t.w, t.h);
        picture = { kind: "picture", caption: "", base64: png, widthPt: prepared.widthPt, heightPt: prepared.heightPt, alt: o.alt };
      } catch (error) {
        figureWhy = (error as Error).message;
      }
    }
  }
  if (insertTextBusy) {
    setStatus("Still inserting the last result — one moment.", "error");
    return false;
  }
  insertTextBusy = true;
  setStatus(`Inserting ${label.toLowerCase()}…`);
  let why = "";
  try {
    const items: ResultPackageItem[] = [{ kind: "text", content: text.replace(/\s+$/, "") }];
    for (const t of tables) {
      // `align`: the regression table centres its model columns (coefficient, "(SE)" and "(1)" on one axis).
      items.push({ kind: "table", label: t.label, rows: t.rows, align: t.align });
      // A table's legend line (E2: the star legend) goes directly under it.
      if (t.note) items.push({ kind: "text", content: t.note });
    }
    if (picture) items.push(picture);
    const built = buildResultOoxml(items);
    const kept = await docHost.insertResultLayout([{ kind: "ooxml", ooxml: built.ooxml }]);
    const what = `${label} and ${tables.length === 1 ? "table" : "tables"}`;
    if (picture && kept !== null && kept < built.pictures) {
      setStatus(`${what} inserted, but ${pictureNotKeptText(png.length)}`, "error");
    } else if (figureWhy) {
      setStatus(`${what} inserted, but the figure could not be: ${figureWhy}`, "error");
    } else {
      setStatus(`${what}${picture ? " and chart" : ""} inserted. Ctrl/⌘+Z undoes it.`, "success");
    }
    return true;
  } catch (error) {
    why = (error as Error).message;
  } finally {
    insertTextBusy = false;
  }
  const plain = [
    text.replace(/\s+$/, ""),
    ...tables.map((t) => t.rows.map((r) => r.join("\t")).join("\n") + (t.note ? `\n${t.note}` : "")),
  ].join("\n\n");
  const ok = await insertPlainText(plain, label);
  if (ok) setStatus(`${label} inserted as plain text (Word refused the table package: ${why}).`, "error");
  return ok;
}

// ---------------------------------------------------------------------------
// The multi-panel tray (v2.143.0)
// ---------------------------------------------------------------------------

/** At most this many panels in the tray (composePanels allows 52; a column figure does not). */
const MAX_TRAY_PANELS = 12;

/** The figure the current tool would insert, as a panel — with its re-render where the tool has one. */
function currentModeFigure(): PanelItem | null {
  switch (currentMode()) {
    case "stats":
      return currentStatsSvg
        ? { svg: currentStatsSvg, render: currentStatsRender ?? undefined, caption: currentStatsCaption || undefined, source: "Statistics" }
        : null;
    case "plot":
      return currentPlotSvg ? { svg: currentPlotSvg, render: currentPlotRender ?? undefined, source: "Plot" } : null;
    case "ppt": {
      const r = renderTableGraphic();
      return r.svg === null ? null : { svg: r.svg, render: tableGraphicRender() ?? undefined, source: "Table → Chart" };
    }
    case "finance":
      return currentFinSvg ? { svg: currentFinSvg, source: "Finance" } : null;
    case "assay":
      return currentAssayPlotSvg ? { svg: currentAssayPlotSvg, source: "Bio/Assay" } : null;
    case "solidform":
      return solidformPane.currentFigure();
    default:
      return null;
  }
}

function updatePanelTray(): void {
  const n = figPanels.length;
  figPanelCount.textContent =
    n === 0
      ? "No panels yet. Add figures from Plot, Table → Chart, Statistics, Finance, Bio/Assay or Solid form, then insert them as one figure."
      : `${n} panel${n === 1 ? "" : "s"}: ${figPanels.map((p, i) => `${i + 1}. ${p.source}`).join(" · ")}` +
        (n < 2 ? ". Add at least one more." : ".");
  figPanelInsertBtn.disabled = n < 2;
  figPanelClearBtn.disabled = n === 0;
  figPanelAddBtn.disabled = n >= MAX_TRAY_PANELS;
}

function addCurrentFigureToPanels(): void {
  // Release D: the figure of the CURRENT input, never one a pending keystroke is about to replace.
  statsPreview.flush();
  solvePreview.flush();
  finPreview.flush();
  const item = currentModeFigure();
  if (!item) {
    setStatus("There is no figure here to add — compute a result with a chart first.", "error");
    return;
  }
  if (figPanels.length >= MAX_TRAY_PANELS) {
    setStatus(`The tray holds at most ${MAX_TRAY_PANELS} panels.`, "error");
    return;
  }
  figPanels.push(item);
  updatePanelTray();
  setStatus(`Added to the panels (${figPanels.length}).`, "success");
}

async function insertPanels(): Promise<void> {
  const cols = Math.min(Number(figPanelCols.value) || 2, figPanels.length);
  const fig = composePanelFigure(figPanels.slice(), currentFigurePreset(), currentFigureWidth(), cols);
  if (!fig.ok) {
    setStatus(`Could not insert the panels: ${refusalText(fig)}`, "error");
    return;
  }
  figPanelInsertBtn.disabled = true;
  setStatus("Inserting the multi-panel figure…");
  try {
    const d = readSvgDims(fig.svg, 380, 260);
    const how = await insertFigure({
      svg: fig.svg,
      fallbackW: d.w,
      fallbackH: d.h,
      alt: `Multi-panel figure: ${fig.labels.map((l, i) => `${l} ${figPanels[i].source}`).join("; ")}${fig.caption ? `. ${fig.caption}` : ""}`,
      tag: "formula-inserter:panels",
      tail: captionTail(fig.caption),
    });
    setStatus(`Multi-panel figure inserted ${how}.`, "success");
  } catch (error) {
    setStatus(`Could not insert the panels: ${(error as Error).message}`, "error");
  } finally {
    updatePanelTray();
  }
}

/**
 * Converts an SVG string to a base64-encoded PNG (no data-URL prefix), which is
 * the format Word's insertInlinePictureFromBase64 expects. Uses an offscreen
 * canvas with a white background so transparent SVG areas don't render black.
 */
function svgToPngBase64(svg: string, width: number, height: number): Promise<string> {
  return new Promise((resolve, reject) => {
    // Encode in chunks: spreading a large byte array into String.fromCharCode(...)
    // overflows the argument/stack limit for big figures (flowcharts, dense plots).
    const bytes = new TextEncoder().encode(svg);
    let binary = "";
    for (let k = 0; k < bytes.length; k += 8192) {
      binary += String.fromCharCode(...bytes.subarray(k, k + 8192));
    }
    const svgBase64 = btoa(binary);
    const img = new Image();

    // A PROMISE THAT NEVER SETTLES IS WORSE THAN ONE THAT REJECTS.
    //
    // The handlers below assume the host fires exactly one of onload/onerror.
    // A host that fires NEITHER — a decode that never completes, a policy that
    // drops the load without reporting it — leaves this promise awaited forever
    // by an insert holding the shared insertTextBusy flag. That flag then never
    // clears, so every later Insert ANYWHERE in the product returns without
    // doing anything, and none of it reaches a catch, a status message or a
    // log. The user sees a button that has quietly stopped working.
    //
    // A callback is not a bound; only a clock is. Ten seconds is far beyond any
    // real rasterisation here (the largest figures take tens of milliseconds)
    // and far short of a user's patience with a dead pane. Every exit runs
    // through done(), so the timer is always cleared and the promise settles
    // exactly once.
    let settled = false;
    const timer = setTimeout(() => {
      done(() => reject(new Error("Rasterizing the figure timed out — it was not inserted.")));
    }, 10000);
    function done(action: () => void): void {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      action();
    }

    img.onload = () => {
      done(() => {
        try {
          const canvas = document.createElement("canvas");
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) throw new Error("Canvas not supported.");
          ctx.fillStyle = "#ffffff";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/png").split(",")[1]);
        } catch (e) {
          reject(e as Error);
        }
      });
    };
    img.onerror = () => done(() => reject(new Error("Could not rasterize the structure image.")));
    img.src = `data:image/svg+xml;base64,${svgBase64}`;
  });
}

